// Original sentence and translation data. Audio is served separately.
const data = [{"n":1,"en":"A good architectural structure should be useful, durable and beautiful.","ko":"좋은 건축 구조물은 실용적이고 내구성이 있으며 아름다워야 한다.","meta":["초빈출","핵심예측","어려움"],"ceb":"Ang maayong estruktura sa arkitektura kinahanglan mapuslanon, lig-on ug matahom.","ja":"優れた建築構造物は、実用的で耐久性があり、美しくあるべきだ。","zh":"优秀的建筑结构应该实用、耐久且美观。","hi":"एक अच्छी वास्तु संरचना उपयोगी, टिकाऊ और सुंदर होनी चाहिए।","es":"Una buena estructura arquitectónica debe ser útil, duradera y hermosa.","vi":"Một công trình kiến trúc tốt phải hữu ích, bền vững và đẹp.","ne":"राम्रो वास्तु संरचना उपयोगी, टिकाउ र सुन्दर हुनुपर्छ।","fil":"Ang isang mahusay na estrukturang arkitektural ay dapat na kapaki-pakinabang, matibay at maganda."},{"n":2,"en":"A group meeting will be held tomorrow in the library conference room.","ko":"내일 도서관 회의실에서 그룹 회의가 열릴 예정이다.","meta":["초빈출","쉬움"],"ceb":"Ang tigom sa grupo ipahigayon ugma sa conference room sa librarya.","ja":"明日、図書館の会議室でグループ会議が開かれる。","zh":"明天将在图书馆会议室举行小组会议。","hi":"कल पुस्तकालय के सम्मेलन कक्ष में समूह बैठक आयोजित होगी।","es":"Mañana se celebrará una reunión de grupo en la sala de conferencias de la biblioteca.","vi":"Một cuộc họp nhóm sẽ được tổ chức vào ngày mai tại phòng hội nghị của thư viện.","ne":"भोलि पुस्तकालयको सम्मेलन कक्षमा समूह बैठक हुनेछ।","fil":"Magkakaroon ng pagpupulong ng grupo bukas sa conference room ng aklatan."},{"n":3,"en":"Educational level is found to be related to social and economic background.","ko":"교육 수준은 사회적, 경제적 배경과 관련이 있는 것으로 나타났다.","meta":["초빈출","핵심예측","보통"],"ceb":"Ang lebel sa edukasyon adunay kalabotan sa sosyal ug ekonomikanhong kahimtang.","ja":"教育水準は社会的・経済的背景と関連していることが分かっている。","zh":"研究发现，教育水平与社会和经济背景有关。","hi":"शिक्षा का स्तर सामाजिक और आर्थिक पृष्ठभूमि से संबंधित पाया गया है।","es":"Se ha observado que el nivel educativo está relacionado con el contexto social y económico.","vi":"Trình độ học vấn được xác định có liên quan đến hoàn cảnh xã hội và kinh tế.","ne":"शैक्षिक स्तर सामाजिक र आर्थिक पृष्ठभूमिसँग सम्बन्धित रहेको पाइन्छ।","fil":"Napag-alamang may kaugnayan ang antas ng edukasyon sa kalagayang panlipunan at pang-ekonomiya."},{"n":4,"en":"All industries are a system of inputs, processes, outputs and feedback.","ko":"모든 산업은 투입, 처리, 산출 및 피드백으로 이루어진 시스템이다.","meta":["초빈출","핵심예측","보통"],"ceb":"Ang tanang industriya usa ka sistema sa mga input, proseso, output ug feedback.","ja":"すべての産業は投入、処理、産出、フィードバックからなるシステムである。","zh":"所有行业都是由投入、过程、产出和反馈组成的系统。","hi":"सभी उद्योग इनपुट, प्रक्रियाओं, आउटपुट और प्रतिक्रिया की एक प्रणाली हैं।","es":"Todas las industrias son un sistema de entradas, procesos, salidas y retroalimentación.","vi":"Mọi ngành công nghiệp đều là một hệ thống gồm đầu vào, quy trình, đầu ra và phản hồi.","ne":"सबै उद्योग आगत, प्रक्रिया, निर्गत र प्रतिक्रियाको प्रणाली हुन्।","fil":"Ang lahat ng industriya ay isang sistema ng mga input, proseso, output at feedback."},{"n":5,"en":"All of the assignments must be submitted in person to the faculty office.","ko":"모든 과제는 학부 사무실에 직접 제출해야 한다.","meta":["초빈출","쉬움"],"ceb":"Ang tanang buluhaton kinahanglan personal nga isumite sa opisina sa faculty.","ja":"すべての課題は学部事務室に直接提出しなければならない。","zh":"所有作业必须亲自提交到院系办公室。","hi":"सभी असाइनमेंट संकाय कार्यालय में व्यक्तिगत रूप से जमा करने होंगे।","es":"Todos los trabajos deben entregarse personalmente en la oficina de la facultad.","vi":"Tất cả bài tập phải được nộp trực tiếp tại văn phòng khoa.","ne":"सबै असाइनमेन्ट संकाय कार्यालयमा व्यक्तिगत रूपमा बुझाउनुपर्छ।","fil":"Ang lahat ng takdang-aralin ay dapat isumite nang personal sa tanggapan ng fakultad."},{"n":6,"en":"Economic development needs to be supported by the government.","ko":"경제 발전에는 정부의 지원이 필요하다.","meta":["초빈출","핵심예측","쉬움"],"ceb":"Ang paglambo sa ekonomiya kinahanglan suportahan sa gobyerno.","ja":"経済発展には政府の支援が必要である。","zh":"经济发展需要政府的支持。","hi":"आर्थिक विकास को सरकार के समर्थन की आवश्यकता है।","es":"El desarrollo económico necesita el apoyo del gobierno.","vi":"Phát triển kinh tế cần được chính phủ hỗ trợ.","ne":"आर्थिक विकासलाई सरकारको समर्थन चाहिन्छ।","fil":"Kailangang suportahan ng pamahalaan ang pag-unlad ng ekonomiya."},{"n":7,"en":"All of your assignments are due by tomorrow.","ko":"모든 과제는 내일까지 제출해야 한다.","meta":["초빈출","핵심예측","쉬움"],"ceb":"Ang tanan nimong buluhaton kinahanglan isumite hangtod ugma.","ja":"すべての課題は明日までに提出しなければならない。","zh":"你所有的作业都必须在明天之前提交。","hi":"आपके सभी असाइनमेंट कल तक जमा होने चाहिए।","es":"Todos tus trabajos deben entregarse a más tardar mañana.","vi":"Tất cả bài tập của bạn phải được nộp chậm nhất vào ngày mai.","ne":"तपाईंका सबै असाइनमेन्ट भोलिसम्म बुझाउनुपर्छ।","fil":"Ang lahat ng iyong takdang-aralin ay kailangang isumite bago matapos ang bukas."},{"n":8,"en":"Our view is that educational reforms have been inadequately implemented.","ko":"우리의 견해는 교육 개혁이 충분히 시행되지 않았다는 것이다.","meta":["초빈출","핵심예측","어려움"],"ceb":"Sa among panglantaw, wala mapatuman ug maayo ang mga reporma sa edukasyon.","ja":"私たちは教育改革が十分に実施されていないと考えている。","zh":"我们认为教育改革没有得到充分实施。","hi":"हमारा विचार है कि शैक्षिक सुधारों को पर्याप्त रूप से लागू नहीं किया गया है।","es":"Consideramos que las reformas educativas se han aplicado de manera inadecuada.","vi":"Quan điểm của chúng tôi là các cải cách giáo dục chưa được thực hiện đầy đủ.","ne":"शैक्षिक सुधारहरू पर्याप्त रूपमा कार्यान्वयन भएका छैनन् भन्ने हाम्रो धारणा हो।","fil":"Ang aming pananaw ay hindi sapat ang pagpapatupad ng mga reporma sa edukasyon."},{"n":9,"en":"Most scientists believe that climate change threatens the lives on earth.","ko":"대부분의 과학자는 기후 변화가 지구상의 생명체를 위협한다고 믿는다.","meta":["초빈출","핵심예측","보통"],"ceb":"Kadaghanan sa mga siyentista nagtuo nga ang kausaban sa klima naghulga sa kinabuhi sa Yuta.","ja":"ほとんどの科学者は気候変動が地球上の生命を脅かすと考えている。","zh":"大多数科学家认为气候变化威胁着地球上的生命。","hi":"अधिकांश वैज्ञानिक मानते हैं कि जलवायु परिवर्तन पृथ्वी पर जीवन को खतरे में डालता है।","es":"La mayoría de los científicos cree que el cambio climático amenaza la vida en la Tierra.","vi":"Hầu hết các nhà khoa học tin rằng biến đổi khí hậu đe dọa sự sống trên Trái Đất.","ne":"धेरैजसो वैज्ञानिकहरू जलवायु परिवर्तनले पृथ्वीको जीवनलाई खतरामा पार्छ भन्ने विश्वास गर्छन्।","fil":"Naniniwala ang karamihan sa mga siyentipiko na nagbabanta sa buhay sa daigdig ang pagbabago ng klima."},{"n":10,"en":"Although sustainable development is not easy, it is an unavoidable responsibility.","ko":"지속 가능한 발전은 쉽지 않지만 피할 수 없는 책임이다.","meta":["초빈출","어려움"],"ceb":"Bisan dili sayon ang malungtarong paglambo, usa kini ka responsibilidad nga dili malikayan.","ja":"持続可能な開発は容易ではないが、避けられない責任である。","zh":"尽管可持续发展并不容易，但它是一项不可回避的责任。","hi":"हालाँकि सतत विकास आसान नहीं है, यह एक अपरिहार्य जिम्मेदारी है।","es":"Aunque el desarrollo sostenible no es fácil, es una responsabilidad inevitable.","vi":"Mặc dù phát triển bền vững không dễ dàng, đó là một trách nhiệm không thể tránh khỏi.","ne":"दिगो विकास सजिलो नभए पनि यो अपरिहार्य जिम्मेवारी हो।","fil":"Bagaman hindi madali ang napapanatiling pag-unlad, ito ay isang hindi maiiwasang responsibilidad."},{"n":11,"en":"Avoid confusing the cause and effect of these changes.","ko":"이러한 변화의 원인과 결과를 혼동하지 않도록 하라.","meta":["초빈출","보통"],"ceb":"Likayi ang paglibog sa hinungdan ug epekto niining mga kausaban.","ja":"これらの変化の原因と結果を混同しないようにしなさい。","zh":"避免混淆这些变化的原因和结果。","hi":"इन परिवर्तनों के कारण और प्रभाव को लेकर भ्रमित होने से बचें।","es":"Evita confundir la causa y el efecto de estos cambios.","vi":"Tránh nhầm lẫn nguyên nhân và kết quả của những thay đổi này.","ne":"यी परिवर्तनका कारण र प्रभावबीच भ्रममा पर्नबाट बच्नुहोस्।","fil":"Iwasang paghaluin ang sanhi at bunga ng mga pagbabagong ito."},{"n":12,"en":"Before completing the exercise, you need to read the remaining chapters.","ko":"연습 문제를 마치기 전에 나머지 장들을 읽어야 한다.","meta":["초빈출","보통"],"ceb":"Sa dili pa nimo humanon ang ehersisyo, basaha ang nahibiling mga kapitulo.","ja":"練習問題を終える前に、残りの章を読む必要がある。","zh":"完成练习之前，你需要阅读剩余章节。","hi":"अभ्यास पूरा करने से पहले आपको शेष अध्याय पढ़ने होंगे।","es":"Antes de completar el ejercicio, debes leer los capítulos restantes.","vi":"Trước khi hoàn thành bài tập, bạn cần đọc các chương còn lại.","ne":"अभ्यास पूरा गर्नुअघि तपाईंले बाँकी अध्यायहरू पढ्नुपर्छ।","fil":"Bago tapusin ang pagsasanay, kailangan mong basahin ang natitirang mga kabanata."},{"n":13,"en":"Consumer confidence has a direct influence on sales.","ko":"소비자 신뢰도는 판매에 직접적인 영향을 미친다.","meta":["초빈출","핵심예측","쉬움"],"ceb":"Ang pagsalig sa mga konsumidor direktang makaapekto sa halin.","ja":"消費者の信頼感は売上に直接影響する。","zh":"消费者信心直接影响销售。","hi":"उपभोक्ताओं के विश्वास का बिक्री पर सीधा प्रभाव पड़ता है।","es":"La confianza del consumidor influye directamente en las ventas.","vi":"Niềm tin của người tiêu dùng ảnh hưởng trực tiếp đến doanh số bán hàng.","ne":"उपभोक्ताको विश्वासले बिक्रीमा प्रत्यक्ष प्रभाव पार्छ।","fil":"Ang tiwala ng mga mamimili ay direktang nakaaapekto sa mga benta."},{"n":14,"en":"Convincing evidence to support this theory is hard to obtain.","ko":"이 이론을 뒷받침할 설득력 있는 증거를 얻기는 어렵다.","meta":["초빈출","핵심예측","보통"],"ceb":"Lisod makakuha og makapakombinsir nga ebidensiya aron suportahan kini nga teoriya.","ja":"この理論を裏付ける説得力のある証拠を得るのは難しい。","zh":"很难获得支持这一理论的有力证据。","hi":"इस सिद्धांत के समर्थन में ठोस प्रमाण प्राप्त करना कठिन है।","es":"Es difícil obtener pruebas convincentes que respalden esta teoría.","vi":"Rất khó tìm được bằng chứng thuyết phục để ủng hộ lý thuyết này.","ne":"यस सिद्धान्तलाई समर्थन गर्ने विश्वसनीय प्रमाण प्राप्त गर्न कठिन छ।","fil":"Mahirap makakuha ng nakakukumbinsing ebidensiya upang suportahan ang teoryang ito."},{"n":15,"en":"Economic problems caused a big rise in unemployment.","ko":"경제 문제로 인해 실업이 크게 증가했다.","meta":["초빈출","쉬움"],"ceb":"Ang mga problema sa ekonomiya hinungdan sa dakong pagsaka sa kawalay trabaho.","ja":"経済問題によって失業が大幅に増加した。","zh":"经济问题导致失业人数大幅增加。","hi":"आर्थिक समस्याओं के कारण बेरोजगारी में भारी वृद्धि हुई।","es":"Los problemas económicos provocaron un gran aumento del desempleo.","vi":"Các vấn đề kinh tế đã khiến tỷ lệ thất nghiệp tăng mạnh.","ne":"आर्थिक समस्याले बेरोजगारीमा ठूलो वृद्धि गरायो।","fil":"Ang mga suliraning pang-ekonomiya ay nagdulot ng malaking pagtaas ng kawalan ng trabaho."},{"n":16,"en":"The economic status of the early Roman Republic will be examined.","ko":"초기 로마 공화국의 경제적 상황을 살펴볼 것이다.","meta":["초빈출","핵심예측","보통"],"ceb":"Susihon ang ekonomikanhong kahimtang sa unang Republika sa Roma.","ja":"初期ローマ共和政の経済状況を検討する。","zh":"将研究早期罗马共和国的经济状况。","hi":"प्रारंभिक रोमन गणराज्य की आर्थिक स्थिति की समीक्षा की जाएगी।","es":"Se examinará la situación económica de la primera República romana.","vi":"Tình trạng kinh tế của Cộng hòa La Mã thời kỳ đầu sẽ được xem xét.","ne":"प्रारम्भिक रोमन गणतन्त्रको आर्थिक अवस्थाको अध्ययन गरिनेछ।","fil":"Susuriin ang kalagayang pang-ekonomiya ng unang Republika ng Roma."},{"n":17,"en":"The academic strength of the early Roman Republic will be examined.","ko":"초기 로마 공화국의 학문적 역량을 살펴볼 것이다.","meta":["초빈출","핵심예측","어려움"],"ceb":"Susihon ang akademikong kalig-on sa unang Republika sa Roma.","ja":"初期ローマ共和政の学問的な強みを検討する。","zh":"将研究早期罗马共和国的学术实力。","hi":"प्रारंभिक रोमन गणराज्य की शैक्षणिक ताकत की समीक्षा की जाएगी।","es":"Se examinará la fortaleza académica de la primera República romana.","vi":"Thế mạnh học thuật của Cộng hòa La Mã thời kỳ đầu sẽ được xem xét.","ne":"प्रारम्भिक रोमन गणतन्त्रको शैक्षिक सामर्थ्यको अध्ययन गरिनेछ।","fil":"Susuriin ang lakas sa larangan ng akademya ng unang Republika ng Roma."},{"n":18,"en":"I thought it was through the small meeting room.","ko":"나는 그 작은 회의실을 통과하는 길인 줄 알았다.","meta":["초빈출","핵심예측","보통"],"ceb":"Abi nako nga agi kini sa gamay nga lawak tigomanan.","ja":"私はその小さな会議室を通るのだと思っていた。","zh":"我以为要穿过那个小会议室。","hi":"मुझे लगा था कि रास्ता छोटे बैठक कक्ष से होकर जाता है।","es":"Pensé que era por la pequeña sala de reuniones.","vi":"Tôi tưởng đường đi là qua phòng họp nhỏ.","ne":"मलाई लागेको थियो कि बाटो सानो बैठक कोठाबाट जान्छ।","fil":"Akala ko ay sa maliit na silid-pulungan ang daan."},{"n":19,"en":"Most university teaching still takes place in lectures and seminars.","ko":"대부분의 대학 교육은 여전히 강의와 세미나를 통해 이루어진다.","meta":["초빈출","핵심예측","보통"],"ceb":"Kadaghanan sa pagtudlo sa unibersidad gihimo gihapon pinaagi sa mga lektyur ug seminar.","ja":"大学教育の大半は今も講義やゼミで行われている。","zh":"大部分大学教学仍通过讲座和研讨会进行。","hi":"विश्वविद्यालय में अधिकांश शिक्षण अब भी व्याख्यानों और संगोष्ठियों के माध्यम से होता है।","es":"La mayor parte de la enseñanza universitaria aún se realiza mediante clases magistrales y seminarios.","vi":"Phần lớn hoạt động giảng dạy ở đại học vẫn diễn ra qua các bài giảng và hội thảo.","ne":"विश्वविद्यालयको अधिकांश शिक्षण अझै पनि व्याख्यान र गोष्ठीमार्फत हुन्छ।","fil":"Karamihan sa pagtuturo sa unibersidad ay isinasagawa pa rin sa pamamagitan ng mga lektura at seminar."},{"n":20,"en":"Native speakers are exempt from the language tests in their own language.","ko":"원어민은 자신의 모국어에 대한 언어 시험을 면제받는다.","meta":["초빈출","핵심예측","어려움"],"ceb":"Ang lumad nga mga mamumulong dili kinahanglan mokuha og eksamin sa ilang kaugalingong pinulongan.","ja":"母語話者は自分の母語の語学試験を免除される。","zh":"母语人士可以免参加其母语的语言测试。","hi":"मूल भाषियों को अपनी भाषा की परीक्षाओं से छूट दी जाती है।","es":"Los hablantes nativos están exentos de los exámenes de su propio idioma.","vi":"Người bản ngữ được miễn các bài kiểm tra ngôn ngữ bằng tiếng mẹ đẻ của họ.","ne":"मातृभाषी वक्ताहरूलाई आफ्नै भाषाको परीक्षाबाट छुट दिइन्छ।","fil":"Ang mga katutubong tagapagsalita ay hindi kailangang kumuha ng mga pagsusulit sa kanilang sariling wika."},{"n":21,"en":"Nurses can specialize in clinical work or management.","ko":"간호사는 임상 업무나 관리 업무를 전문으로 할 수 있다.","meta":["초빈출","핵심예측","보통"],"ceb":"Ang mga nars mahimong mag-espesyalisa sa klinikal nga trabaho o pagdumala.","ja":"看護師は臨床業務や管理業務を専門にできる。","zh":"护士可以专攻临床工作或管理。","hi":"नर्सें नैदानिक कार्य या प्रबंधन में विशेषज्ञता प्राप्त कर सकती हैं।","es":"El personal de enfermería puede especializarse en el trabajo clínico o la gestión.","vi":"Điều dưỡng viên có thể chuyên về công tác lâm sàng hoặc quản lý.","ne":"नर्सहरूले क्लिनिकल काम वा व्यवस्थापनमा विशेषज्ञता हासिल गर्न सक्छन्।","fil":"Maaaring magpakadalubhasa ang mga nars sa klinikal na trabaho o pamamahala."},{"n":22,"en":"Our professor is hosting the business development conference.","ko":"우리 교수님은 사업 개발 회의를 주최하고 있다.","meta":["초빈출","핵심예측","쉬움"],"ceb":"Ang among propesor nag-host sa komperensiya bahin sa pagpalambo sa negosyo.","ja":"私たちの教授は事業開発会議を主催している。","zh":"我们的教授正在主持商业发展会议。","hi":"हमारे प्रोफेसर व्यवसाय विकास सम्मेलन की मेजबानी कर रहे हैं।","es":"Nuestro profesor organiza la conferencia sobre desarrollo empresarial.","vi":"Giáo sư của chúng tôi đang chủ trì hội nghị phát triển kinh doanh.","ne":"हाम्रा प्राध्यापकले व्यवसाय विकास सम्मेलनको आयोजना गरिरहेका छन्।","fil":"Ang aming propesor ang nangangasiwa sa kumperensiya tungkol sa pagpapaunlad ng negosyo."},{"n":23,"en":"Packaging is very important to attract the attention of a buyer.","ko":"포장은 구매자의 관심을 끄는 데 매우 중요하다.","meta":["초빈출","핵심예측","보통"],"ceb":"Importante kaayo ang pagputos aron madani ang atensiyon sa mamalitay.","ja":"包装は購入者の注意を引くために非常に重要である。","zh":"包装对于吸引买家的注意力非常重要。","hi":"खरीदार का ध्यान आकर्षित करने के लिए पैकेजिंग बहुत महत्वपूर्ण है।","es":"El embalaje es muy importante para atraer la atención del comprador.","vi":"Bao bì rất quan trọng trong việc thu hút sự chú ý của người mua.","ne":"क्रेताको ध्यान आकर्षित गर्न प्याकेजिङ धेरै महत्त्वपूर्ण हुन्छ।","fil":"Napakahalaga ng pag-iimpake upang makuha ang atensiyon ng mamimili."},{"n":24,"en":"Plants are the living things that can grow on land or in water.","ko":"식물은 육지나 물에서 자랄 수 있는 생물이다.","meta":["초빈출","쉬움"],"ceb":"Ang mga tanom mga buhing butang nga motubo sa yuta o sa tubig.","ja":"植物は陸上や水中で成長できる生物である。","zh":"植物是可以在陆地或水中生长的生物。","hi":"पौधे ऐसे जीवित प्राणी हैं जो भूमि या पानी में उग सकते हैं।","es":"Las plantas son seres vivos que pueden crecer en tierra o en agua.","vi":"Thực vật là những sinh vật có thể phát triển trên cạn hoặc dưới nước.","ne":"वनस्पति जमिन वा पानीमा उम्रन सक्ने जीवित वस्तु हुन्।","fil":"Ang mga halaman ay mga buhay na organismo na maaaring tumubo sa lupa o tubig."},{"n":25,"en":"Please check the information on the website for the opening times.","ko":"운영 시간은 웹사이트에서 정보를 확인해 주세요.","meta":["초빈출","핵심예측","쉬움"],"ceb":"Palihog susiha ang impormasyon sa website bahin sa oras sa pag-abli.","ja":"開館時間についてはウェブサイトの情報を確認してください。","zh":"请查看网站上的开放时间信息。","hi":"कृपया खुलने के समय की जानकारी वेबसाइट पर देखें।","es":"Consulta la información del sitio web para conocer el horario de apertura.","vi":"Vui lòng kiểm tra thông tin trên trang web để biết giờ mở cửa.","ne":"खुल्ने समयको जानकारीका लागि कृपया वेबसाइट हेर्नुहोस्।","fil":"Pakisuri ang impormasyon sa website para malaman ang oras ng pagbubukas."},{"n":26,"en":"Remember to sign the attendance register before leaving the lecture hall.","ko":"강의실을 떠나기 전에 출석부에 서명하는 것을 잊지 마세요.","meta":["초빈출","보통"],"ceb":"Hinumdomi ang pagpirma sa attendance register sa dili pa mogawas sa lecture hall.","ja":"講義室を出る前に出席簿に署名することを忘れないでください。","zh":"离开讲堂前记得在出勤登记表上签名。","hi":"व्याख्यान कक्ष छोड़ने से पहले उपस्थिति रजिस्टर पर हस्ताक्षर करना याद रखें।","es":"Recuerda firmar el registro de asistencia antes de salir del aula.","vi":"Hãy nhớ ký vào sổ điểm danh trước khi rời giảng đường.","ne":"व्याख्यान कक्ष छोड्नुअघि हाजिरी पुस्तिकामा हस्ताक्षर गर्न नबिर्सनुहोस्।","fil":"Tandaang pumirma sa talaan ng pagdalo bago umalis sa bulwagan ng lektura."},{"n":27,"en":"The supposed benefits of space exploration are frequently questioned.","ko":"우주 탐사의 이른바 이점은 자주 의문을 제기받는다.","meta":["초빈출","어려움"],"ceb":"Ang gituohang mga benepisyo sa eksplorasyon sa kawanangan kanunay nga gikuwestiyon.","ja":"宇宙探査の利点とされるものにはしばしば疑問が呈される。","zh":"太空探索所谓的好处经常受到质疑。","hi":"अंतरिक्ष अन्वेषण के कथित लाभों पर अक्सर सवाल उठाए जाते हैं।","es":"Los supuestos beneficios de la exploración espacial se cuestionan con frecuencia.","vi":"Những lợi ích được cho là của việc khám phá không gian thường bị đặt dấu hỏi.","ne":"अन्तरिक्ष अन्वेषणका कथित फाइदाहरूमाथि प्रायः प्रश्न उठाइन्छ।","fil":"Madalas kuwestiyunin ang mga sinasabing pakinabang ng paggalugad sa kalawakan."},{"n":28,"en":"Scientists are always asking the government for more money.","ko":"과학자들은 항상 정부에 더 많은 자금을 요청한다.","meta":["초빈출","핵심예측","쉬움"],"ceb":"Ang mga siyentista kanunay mangayo og dugang kuwarta sa gobyerno.","ja":"科学者たちは常に政府にさらなる資金を求めている。","zh":"科学家总是在向政府要求更多资金。","hi":"वैज्ञानिक हमेशा सरकार से अधिक धन की मांग करते रहते हैं।","es":"Los científicos siempre piden más dinero al gobierno.","vi":"Các nhà khoa học luôn yêu cầu chính phủ cấp thêm tiền.","ne":"वैज्ञानिकहरूले सधैँ सरकारसँग थप पैसा मागिरहेका हुन्छन्।","fil":"Palaging humihingi ang mga siyentipiko ng karagdagang pondo sa pamahalaan."},{"n":29,"en":"The speaker began by giving an outline of her presentation.","ko":"발표자는 자신의 발표 개요를 설명하는 것으로 시작했다.","meta":["초빈출","핵심예측","보통"],"ceb":"Ang mamumulong nagsugod pinaagi sa paghatag og kinatibuk-ang hulagway sa iyang presentasyon.","ja":"講演者は発表の概要を説明することから始めた。","zh":"演讲者首先概述了她的演讲内容。","hi":"वक्ता ने अपनी प्रस्तुति की रूपरेखा बताकर शुरुआत की।","es":"La oradora comenzó ofreciendo un resumen de su presentación.","vi":"Diễn giả bắt đầu bằng cách trình bày khái quát bài thuyết trình của mình.","ne":"वक्ताले आफ्नो प्रस्तुतिको रूपरेखा दिएर सुरु गरिन्।","fil":"Nagsimula ang tagapagsalita sa pagbibigay ng balangkas ng kanyang presentasyon."},{"n":30,"en":"Statistical results should be expressed in different ways depending on the circumstances.","ko":"통계 결과는 상황에 따라 다양한 방식으로 표현되어야 한다.","meta":["초빈출","핵심예측","어려움"],"ceb":"Ang estadistikang mga resulta kinahanglan ipahayag sa lainlaing paagi depende sa kahimtang.","ja":"統計結果は状況に応じて異なる方法で表現すべきである。","zh":"统计结果应根据不同情况以不同方式表达。","hi":"परिस्थितियों के अनुसार सांख्यिकीय परिणामों को अलग-अलग तरीकों से व्यक्त किया जाना चाहिए।","es":"Los resultados estadísticos deben expresarse de distintas maneras según las circunstancias.","vi":"Kết quả thống kê nên được trình bày theo nhiều cách khác nhau tùy hoàn cảnh.","ne":"परिस्थितिअनुसार तथ्याङ्कीय नतिजाहरू फरकफरक तरिकाले व्यक्त गरिनुपर्छ।","fil":"Dapat ipahayag ang mga resulta ng estadistika sa iba't ibang paraan depende sa mga pangyayari."},{"n":31,"en":"You are advised to use multiple research methods for this project.","ko":"이 프로젝트에 여러 연구 방법을 사용하는 것이 권장된다.","meta":["초빈출","핵심예측","보통"],"ceb":"Gitambagan ka nga mogamit og daghang pamaagi sa panukiduki alang niini nga proyekto.","ja":"このプロジェクトでは複数の研究方法を用いることが推奨される。","zh":"建议你在这个项目中使用多种研究方法。","hi":"आपको इस परियोजना के लिए कई शोध विधियों का उपयोग करने की सलाह दी जाती है।","es":"Se recomienda utilizar varios métodos de investigación para este proyecto.","vi":"Bạn được khuyên sử dụng nhiều phương pháp nghiên cứu cho dự án này.","ne":"यस परियोजनाका लागि विभिन्न अनुसन्धान विधिहरू प्रयोग गर्न तपाईंलाई सल्लाह दिइन्छ।","fil":"Pinapayuhan kang gumamit ng maraming pamamaraan ng pananaliksik para sa proyektong ito."},{"n":32,"en":"Students who are successful have good strategies for learning.","ko":"성공적인 학생들은 좋은 학습 전략을 가지고 있다.","meta":["초빈출","핵심예측","보통"],"ceb":"Ang malampusong mga estudyante adunay maayong mga estratehiya sa pagkat-on.","ja":"成功する学生は優れた学習戦略を持っている。","zh":"成功的学生拥有良好的学习策略。","hi":"सफल विद्यार्थियों के पास सीखने की अच्छी रणनीतियाँ होती हैं।","es":"Los estudiantes que tienen éxito cuentan con buenas estrategias de aprendizaje.","vi":"Những sinh viên thành công có các chiến lược học tập tốt.","ne":"सफल विद्यार्थीहरूसँग सिकाइका राम्रा रणनीतिहरू हुन्छन्।","fil":"Ang mga matagumpay na estudyante ay may magagandang estratehiya sa pag-aaral."},{"n":33,"en":"Textile manufacturing plays a large role in improving economies.","ko":"섬유 제조업은 경제를 개선하는 데 큰 역할을 한다.","meta":["초빈출","보통"],"ceb":"Ang paghimo og tela adunay dakong papel sa pagpauswag sa ekonomiya.","ja":"繊維製造業は経済の改善に大きな役割を果たす。","zh":"纺织制造业在促进经济发展方面发挥着重要作用。","hi":"वस्त्र निर्माण अर्थव्यवस्थाओं को बेहतर बनाने में बड़ी भूमिका निभाता है।","es":"La fabricación textil desempeña un papel importante en la mejora de las economías.","vi":"Sản xuất hàng dệt may đóng vai trò lớn trong việc cải thiện các nền kinh tế.","ne":"कपडा उत्पादनले अर्थतन्त्र सुधार्न ठूलो भूमिका खेल्छ।","fil":"Malaki ang papel ng paggawa ng tela sa pagpapabuti ng mga ekonomiya."},{"n":34,"en":"Food that contains antibiotics provides little or no nutritional value.","ko":"항생제가 들어 있는 식품은 영양가가 거의 없거나 전혀 없다.","meta":["초빈출","어려움"],"ceb":"Ang pagkaon nga adunay antibiotics adunay gamay o walay sustansiya.","ja":"抗生物質を含む食品には栄養価がほとんど、あるいは全くない。","zh":"含有抗生素的食物几乎没有营养价值。","hi":"एंटीबायोटिक युक्त भोजन में बहुत कम या कोई पोषण मूल्य नहीं होता।","es":"Los alimentos que contienen antibióticos tienen poco o ningún valor nutricional.","vi":"Thực phẩm chứa kháng sinh có ít hoặc không có giá trị dinh dưỡng.","ne":"एन्टिबायोटिक भएको खानामा थोरै वा कुनै पनि पोषण मूल्य हुँदैन।","fil":"Ang pagkaing naglalaman ng antibiyotiko ay may kaunti o walang halagang nutrisyonal."},{"n":35,"en":"The business policy seminar includes an internship with a local firm.","ko":"경영 정책 세미나에는 현지 기업에서의 인턴십이 포함된다.","meta":["초빈출","보통"],"ceb":"Ang seminar sa polisiya sa negosyo naglakip og internship sa lokal nga kompanya.","ja":"経営方針のゼミには地元企業でのインターンシップが含まれる。","zh":"商业政策研讨会包括在当地公司的实习。","hi":"व्यावसायिक नीति की संगोष्ठी में एक स्थानीय कंपनी में इंटर्नशिप शामिल है।","es":"El seminario de política empresarial incluye prácticas en una empresa local.","vi":"Hội thảo về chính sách kinh doanh bao gồm kỳ thực tập tại một công ty địa phương.","ne":"व्यावसायिक नीतिसम्बन्धी गोष्ठीमा स्थानीय कम्पनीमा इन्टर्नसिप समावेश छ।","fil":"Kasama sa seminar tungkol sa patakaran ng negosyo ang internship sa isang lokal na kompanya."},{"n":36,"en":"The cafeteria features soup, salads, sandwiches, chicken and fish.","ko":"구내식당에서는 수프, 샐러드, 샌드위치, 닭고기와 생선을 제공한다.","meta":["초빈출","핵심예측","어려움"],"ceb":"Ang cafeteria adunay sabaw, salad, sandwich, manok ug isda.","ja":"カフェテリアではスープ、サラダ、サンドイッチ、鶏肉、魚を提供している。","zh":"自助餐厅供应汤、沙拉、三明治、鸡肉和鱼。","hi":"कैफेटेरिया में सूप, सलाद, सैंडविच, चिकन और मछली मिलती है।","es":"La cafetería ofrece sopa, ensaladas, sándwiches, pollo y pescado.","vi":"Căng tin phục vụ súp, salad, bánh mì kẹp, thịt gà và cá.","ne":"क्यान्टिनमा सुप, सलाद, स्यान्डविच, कुखुराको मासु र माछा पाइन्छ।","fil":"Nag-aalok ang kantina ng sopas, salad, sandwich, manok at isda."},{"n":37,"en":"The chemistry building is located near the entrance to the campus.","ko":"화학관은 캠퍼스 입구 근처에 위치해 있다.","meta":["초빈출","보통"],"ceb":"Ang bilding sa chemistry nahimutang duol sa entrada sa campus.","ja":"化学棟はキャンパスの入り口近くにある。","zh":"化学楼位于校园入口附近。","hi":"रसायन विज्ञान की इमारत परिसर के प्रवेश द्वार के पास स्थित है।","es":"El edificio de química está situado cerca de la entrada del campus.","vi":"Tòa nhà hóa học nằm gần lối vào khuôn viên trường.","ne":"रसायनशास्त्रको भवन क्याम्पसको प्रवेशद्वार नजिकै छ।","fil":"Ang gusali ng kimika ay malapit sa pasukan ng kampus."},{"n":38,"en":"The course will help students to improve their pronunciation skills.","ko":"이 과정은 학생들의 발음 능력 향상에 도움이 될 것이다.","meta":["초빈출","핵심예측","쉬움"],"ceb":"Ang kurso makatabang sa mga estudyante sa pagpauswag sa ilang paglitok.","ja":"この講座は学生の発音能力の向上に役立つ。","zh":"这门课程将帮助学生提高发音技能。","hi":"यह पाठ्यक्रम विद्यार्थियों के उच्चारण कौशल को सुधारने में मदद करेगा।","es":"El curso ayudará a los estudiantes a mejorar sus habilidades de pronunciación.","vi":"Khóa học sẽ giúp sinh viên cải thiện kỹ năng phát âm.","ne":"यस पाठ्यक्रमले विद्यार्थीहरूको उच्चारण सीप सुधार्न मद्दत गर्नेछ।","fil":"Tutulungan ng kurso ang mga estudyante na pagbutihin ang kanilang pagbigkas."},{"n":39,"en":"The designers will complete the plan later today.","ko":"디자이너들은 오늘 늦게 설계도를 완성할 것이다.","meta":["초빈출","핵심예측","쉬움"],"ceb":"Humanon sa mga designer ang plano unya karong adlawa.","ja":"デザイナーたちは今日中に計画を完成させる。","zh":"设计师将在今天晚些时候完成计划。","hi":"डिजाइनर आज बाद में योजना पूरी करेंगे।","es":"Los diseñadores terminarán el plan más tarde hoy.","vi":"Các nhà thiết kế sẽ hoàn thành bản kế hoạch vào cuối ngày hôm nay.","ne":"डिजाइनरहरूले आजै पछि योजना पूरा गर्नेछन्।","fil":"Tatapusin ng mga taga-disenyo ang plano mamaya ngayong araw."},{"n":40,"en":"The faculty staff are very approachable, friendly and extremely helpful.","ko":"교직원들은 다가가기 쉽고 친절하며 매우 적극적으로 도와준다.","meta":["초빈출","핵심예측","보통"],"ceb":"Ang mga kawani sa faculty daling duolon, mahigalaon ug matinabangon kaayo.","ja":"学部の職員は話しかけやすく、親切で非常に協力的である。","zh":"院系工作人员平易近人、友善且非常乐于助人。","hi":"संकाय के कर्मचारी बहुत मिलनसार, मित्रवत और अत्यंत मददगार हैं।","es":"El personal de la facultad es muy accesible, amable y sumamente servicial.","vi":"Nhân viên của khoa rất dễ tiếp cận, thân thiện và vô cùng nhiệt tình giúp đỡ.","ne":"संकायका कर्मचारीहरू सजिलै सम्पर्क गर्न सकिने, मिलनसार र अत्यन्त सहयोगी छन्।","fil":"Ang mga kawani ng fakultad ay madaling lapitan, palakaibigan at lubhang matulungin."},{"n":41,"en":"The summer course is canceled due to insufficient enrollment.","ko":"등록 인원 부족으로 여름 과정이 취소되었다.","meta":["초빈출","핵심예측","보통"],"ceb":"Gikansela ang summer course tungod sa kakulang sa mga nagpalista.","ja":"夏期講座は受講登録者が少ないため中止された。","zh":"由于报名人数不足，暑期课程被取消。","hi":"पर्याप्त नामांकन न होने के कारण ग्रीष्मकालीन पाठ्यक्रम रद्द कर दिया गया है।","es":"El curso de verano se cancela por falta de inscripciones.","vi":"Khóa học mùa hè bị hủy do không đủ người đăng ký.","ne":"पर्याप्त विद्यार्थी भर्ना नभएकाले ग्रीष्मकालीन पाठ्यक्रम रद्द गरिएको छ।","fil":"Kinansela ang kurso sa tag-init dahil kulang ang mga nagpatala."},{"n":42,"en":"The new technician dropped the microscope in the biology lab.","ko":"새로 온 기술자가 생물학 실험실에서 현미경을 떨어뜨렸다.","meta":["초빈출","보통"],"ceb":"Nahulog sa bag-ong technician ang microscope sa biology lab.","ja":"新しい技術員が生物学実験室で顕微鏡を落とした。","zh":"新来的技术员在生物实验室弄掉了显微镜。","hi":"नए तकनीशियन ने जीव विज्ञान प्रयोगशाला में सूक्ष्मदर्शी गिरा दिया।","es":"El nuevo técnico dejó caer el microscopio en el laboratorio de biología.","vi":"Kỹ thuật viên mới làm rơi kính hiển vi trong phòng thí nghiệm sinh học.","ne":"नयाँ प्राविधिकले जीवविज्ञान प्रयोगशालामा सूक्ष्मदर्शक खसाले।","fil":"Nahulog ng bagong teknisyan ang mikroskopyo sa laboratoryo ng biyolohiya."},{"n":43,"en":"The theme of the instrumental work exhibits more of a demure compositional style.","ko":"그 기악곡의 주제는 비교적 차분하고 절제된 작곡 양식을 보여 준다.","meta":["초빈출","핵심예측","어려움"],"ceb":"Ang tema sa instrumental nga komposisyon nagpakita og mas hinay ug dili mapasigarbohong estilo.","ja":"その器楽曲の主題は比較的控えめな作曲様式を示している。","zh":"这部器乐作品的主题体现出较为含蓄的作曲风格。","hi":"वाद्य संगीत रचना का विषय अपेक्षाकृत संयमित रचना शैली दर्शाता है।","es":"El tema de la obra instrumental muestra un estilo de composición más bien discreto.","vi":"Chủ đề của tác phẩm nhạc không lời thể hiện phong cách sáng tác khá kín đáo.","ne":"वाद्य सङ्गीत रचनाको विषयवस्तुले तुलनात्मक रूपमा संयमित रचना शैली देखाउँछ।","fil":"Ang tema ng instrumental na komposisyon ay nagpapakita ng mas mahinahon at payak na estilo ng paglikha."},{"n":44,"en":"The visiting speaker used to be a lecturer in this department.","ko":"방문 연사는 이전에 이 학과의 강사였다.","meta":["초빈출","핵심예측","쉬움"],"ceb":"Ang bisitang mamumulong kaniadto usa ka lecturer niini nga departamento.","ja":"訪問講演者は以前この学科の講師だった。","zh":"来访演讲者曾是本系的讲师。","hi":"अतिथि वक्ता पहले इस विभाग में व्याख्याता थे।","es":"El ponente invitado fue anteriormente profesor de este departamento.","vi":"Diễn giả khách mời từng là giảng viên của khoa này.","ne":"अतिथि वक्ता पहिले यस विभागका व्याख्याता थिए।","fil":"Ang panauhing tagapagsalita ay dating lektor sa departamentong ito."},{"n":45,"en":"Our laboratory equipment is provided free of charge.","ko":"우리의 실험실 장비는 무료로 제공된다.","meta":["초빈출","핵심예측","보통"],"ceb":"Libre nga gihatag ang among mga kagamitan sa laboratoryo.","ja":"私たちの実験設備は無料で提供される。","zh":"我们的实验室设备免费提供。","hi":"हमारे प्रयोगशाला उपकरण निःशुल्क उपलब्ध कराए जाते हैं।","es":"Nuestro equipo de laboratorio se proporciona gratuitamente.","vi":"Thiết bị phòng thí nghiệm của chúng tôi được cung cấp miễn phí.","ne":"हाम्रा प्रयोगशालाका उपकरणहरू निःशुल्क उपलब्ध गराइन्छन्।","fil":"Ibinibigay nang libre ang aming kagamitan sa laboratoryo."},{"n":46,"en":"Traffic is the main cause of air pollution in many cities.","ko":"많은 도시에서 교통은 대기 오염의 주요 원인이다.","meta":["초빈출","핵심예측","쉬움"],"ceb":"Ang trapiko mao ang pangunang hinungdan sa polusyon sa hangin sa daghang siyudad.","ja":"多くの都市で交通が大気汚染の主な原因である。","zh":"交通是许多城市空气污染的主要原因。","hi":"कई शहरों में वायु प्रदूषण का मुख्य कारण यातायात है।","es":"El tráfico es la principal causa de la contaminación del aire en muchas ciudades.","vi":"Giao thông là nguyên nhân chính gây ô nhiễm không khí ở nhiều thành phố.","ne":"धेरै सहरमा वायु प्रदूषणको मुख्य कारण यातायात हो।","fil":"Ang trapiko ang pangunahing sanhi ng polusyon sa hangin sa maraming lungsod."},{"n":47,"en":"It would be extremely beneficial to work together.","ko":"함께 일하는 것은 매우 유익할 것이다.","meta":["초빈출","핵심예측","쉬움"],"ceb":"Dako kaayo ang kaayohan sa pagtinabangay.","ja":"協力することは非常に有益だろう。","zh":"共同合作将极为有益。","hi":"मिलकर काम करना अत्यंत लाभदायक होगा।","es":"Sería sumamente beneficioso trabajar juntos.","vi":"Làm việc cùng nhau sẽ vô cùng có lợi.","ne":"मिलेर काम गर्नु अत्यन्त लाभदायक हुनेछ।","fil":"Lubhang kapaki-pakinabang ang pagtutulungan."},{"n":48,"en":"Understanding how to use the library will save your time.","ko":"도서관 이용 방법을 이해하면 시간을 절약할 수 있다.","meta":["초빈출","쉬움"],"ceb":"Ang pagkahibalo sa paggamit sa librarya makadaginot sa imong oras.","ja":"図書館の利用方法を理解すれば時間を節約できる。","zh":"了解如何使用图书馆将节省你的时间。","hi":"पुस्तकालय का उपयोग करना समझने से आपका समय बचेगा।","es":"Saber utilizar la biblioteca te ahorrará tiempo.","vi":"Biết cách sử dụng thư viện sẽ giúp bạn tiết kiệm thời gian.","ne":"पुस्तकालय कसरी प्रयोग गर्ने भन्ने बुझ्दा तपाईंको समय बच्नेछ।","fil":"Ang pag-alam kung paano gamitin ang aklatan ay makatitipid sa iyong oras."},{"n":49,"en":"University fees are expected to increase next year.","ko":"내년에 대학 등록금이 인상될 것으로 예상된다.","meta":["초빈출","핵심예측","쉬움"],"ceb":"Gilaoman nga mosaka ang bayranan sa unibersidad sunod tuig.","ja":"大学の授業料は来年上がると予想されている。","zh":"预计明年大学学费将上涨。","hi":"अगले वर्ष विश्वविद्यालय की फीस बढ़ने की उम्मीद है।","es":"Se espera que las tasas universitarias aumenten el próximo año.","vi":"Học phí đại học dự kiến sẽ tăng vào năm tới.","ne":"अर्को वर्ष विश्वविद्यालयको शुल्क बढ्ने अपेक्षा गरिएको छ।","fil":"Inaasahang tataas ang mga bayarin sa unibersidad sa susunod na taon."},{"n":50,"en":"Years of training are needed to become a medical specialist.","ko":"의학 전문가가 되려면 수년간의 훈련이 필요하다.","meta":["초빈출","핵심예측","보통"],"ceb":"Gikinahanglan ang daghang tuig nga pagbansay aron mahimong espesyalista sa medisina.","ja":"医療の専門家になるには何年もの訓練が必要である。","zh":"成为医学专家需要多年的培训。","hi":"चिकित्सा विशेषज्ञ बनने के लिए वर्षों के प्रशिक्षण की आवश्यकता होती है।","es":"Se necesitan años de formación para convertirse en especialista médico.","vi":"Cần nhiều năm đào tạo để trở thành bác sĩ chuyên khoa.","ne":"चिकित्सा विशेषज्ञ बन्न वर्षौँको तालिम आवश्यक पर्छ।","fil":"Kailangan ng maraming taon ng pagsasanay upang maging espesyalista sa medisina."},{"n":51,"en":"Manufacturing can now employ more people than agriculture and fishing combined.","ko":"이제 제조업은 농업과 어업을 합친 것보다 더 많은 사람을 고용할 수 있다.","meta":["초빈출","핵심예측","어려움"],"ceb":"Ang manufacturing karon makahatag og trabaho sa mas daghang tawo kay sa agrikultura ug pangisda nga gihiusa.","ja":"現在、製造業は農業と漁業を合わせたよりも多くの人を雇用できる。","zh":"如今制造业能雇用的人数超过农业和渔业的总和。","hi":"अब विनिर्माण उद्योग कृषि और मत्स्य पालन को मिलाकर भी उनसे अधिक लोगों को रोजगार दे सकता है।","es":"La industria manufacturera puede emplear ahora a más personas que la agricultura y la pesca juntas.","vi":"Ngành sản xuất hiện có thể tuyển dụng nhiều người hơn cả nông nghiệp và đánh bắt cá cộng lại.","ne":"उत्पादन उद्योगले अहिले कृषि र माछा मार्ने व्यवसायले संयुक्त रूपमा भन्दा बढी मानिसलाई रोजगारी दिन सक्छ।","fil":"Mas maraming tao na ngayon ang maaaring mabigyan ng trabaho ng industriya ng pagmamanupaktura kaysa sa agrikultura at pangingisda na pinagsama."},{"n":52,"en":"Global connections thrived in academic communities, thanks to social media.","ko":"소셜 미디어 덕분에 학계의 국제적 교류가 활발해졌다.","meta":["초빈출","핵심예측","어려움"],"ceb":"Milambo ang global nga koneksiyon sa akademikong komunidad tungod sa social media.","ja":"ソーシャルメディアのおかげで学術界の国際的なつながりが活発になった。","zh":"得益于社交媒体，学术界的全球联系蓬勃发展。","hi":"सोशल मीडिया के कारण शैक्षणिक समुदायों में वैश्विक संबंध फले-फूले।","es":"Las conexiones mundiales prosperaron en las comunidades académicas gracias a las redes sociales.","vi":"Nhờ mạng xã hội, các mối liên kết toàn cầu phát triển mạnh trong cộng đồng học thuật.","ne":"सामाजिक सञ्जालका कारण शैक्षिक समुदायमा विश्वव्यापी सम्बन्धहरू फस्टाए।","fil":"Umunlad ang mga pandaigdigang ugnayan sa mga komunidad ng akademya dahil sa social media."},{"n":53,"en":"Mature students usually adapt to university life extremely well.","ko":"성인 학생들은 대개 대학 생활에 매우 잘 적응한다.","meta":["초빈출","핵심예측","보통"],"ceb":"Ang mga estudyanteng hamtong kasagarang maayo kaayo nga makapasibo sa kinabuhi sa unibersidad.","ja":"成人学生はたいてい大学生活に非常によく適応する。","zh":"成年学生通常非常适应大学生活。","hi":"वयस्क विद्यार्थी आमतौर पर विश्वविद्यालय के जीवन में बहुत अच्छी तरह ढल जाते हैं।","es":"Los estudiantes adultos suelen adaptarse muy bien a la vida universitaria.","vi":"Sinh viên trưởng thành thường thích nghi rất tốt với cuộc sống đại học.","ne":"वयस्क विद्यार्थीहरू सामान्यतया विश्वविद्यालय जीवनमा निकै राम्रोसँग घुलमिल हुन्छन्।","fil":"Karaniwang napakahusay makibagay sa buhay-unibersidad ang mga estudyanteng nasa hustong gulang."},{"n":54,"en":"The science library is currently located on the ground floor of the library.","ko":"과학 도서관은 현재 도서관의 지상층(1층)에 위치해 있다.","meta":["초빈출","핵심예측","쉬움"],"ceb":"Ang science library nahimutang karon sa ground floor sa librarya.","ja":"科学図書館は現在、図書館の地上階にある。","zh":"科学图书馆目前位于图书馆的底层。","hi":"विज्ञान पुस्तकालय वर्तमान में पुस्तकालय के भूतल पर स्थित है।","es":"La biblioteca de ciencias se encuentra actualmente en la planta baja de la biblioteca.","vi":"Thư viện khoa học hiện nằm ở tầng trệt của thư viện.","ne":"विज्ञान पुस्तकालय हाल पुस्तकालयको भुइँतलामा अवस्थित छ।","fil":"Ang aklatan ng agham ay kasalukuyang nasa palapag sa antas ng lupa ng aklatan."},{"n":55,"en":"Several candidates would be qualified as the greatest scientists of all time.","ko":"몇몇 후보자는 역사상 가장 위대한 과학자로 인정받을 자격이 있을 것이다.","meta":["초빈출","핵심예측","보통"],"ceb":"Daghang kandidato ang mahimong isipon nga labing bantog nga siyentista sa tanang panahon.","ja":"何人かの候補者は史上最も偉大な科学者と呼ぶにふさわしいだろう。","zh":"几位候选人有资格被称为有史以来最伟大的科学家。","hi":"कई उम्मीदवारों को अब तक के महानतम वैज्ञानिकों में गिने जाने योग्य माना जा सकता है।","es":"Varios candidatos podrían ser considerados los mejores científicos de todos los tiempos.","vi":"Một số ứng viên có thể đủ tiêu chuẩn được coi là những nhà khoa học vĩ đại nhất mọi thời đại.","ne":"केही उम्मेदवारहरूलाई अहिलेसम्मका महान् वैज्ञानिकहरूमध्ये गनिन योग्य मान्न सकिन्छ।","fil":"Maraming kandidato ang maaaring maging karapat-dapat na ituring na pinakadakilang siyentipiko sa lahat ng panahon."},{"n":56,"en":"Students are advised that the lecture today has been canceled.","ko":"학생들은 오늘 강의가 취소되었다는 안내를 받았다.","meta":["초빈출","핵심예측","보통"],"ceb":"Gipahibalo ang mga estudyante nga gikansela ang lektyur karong adlawa.","ja":"学生たちには今日の講義が中止されたと通知されている。","zh":"学生们被告知今天的讲座已取消。","hi":"विद्यार्थियों को सूचित किया जाता है कि आज का व्याख्यान रद्द कर दिया गया है।","es":"Se informa a los estudiantes de que la clase de hoy ha sido cancelada.","vi":"Sinh viên được thông báo rằng bài giảng hôm nay đã bị hủy.","ne":"आजको व्याख्यान रद्द गरिएको जानकारी विद्यार्थीहरूलाई दिइन्छ।","fil":"Pinababatid sa mga estudyante na kinansela ang lektura ngayong araw."},{"n":57,"en":"The Industrial Revolution in Europe was driven by steam technology.","ko":"유럽의 산업 혁명은 증기 기술에 의해 추진되었다.","meta":["초빈출","핵심예측","보통"],"ceb":"Ang Industrial Revolution sa Europa gipadagan sa teknolohiya sa alisngaw.","ja":"ヨーロッパの産業革命は蒸気技術によって推進された。","zh":"欧洲工业革命由蒸汽技术推动。","hi":"यूरोप में औद्योगिक क्रांति भाप प्रौद्योगिकी से प्रेरित थी।","es":"La Revolución Industrial en Europa fue impulsada por la tecnología del vapor.","vi":"Cuộc Cách mạng Công nghiệp ở châu Âu được thúc đẩy bởi công nghệ hơi nước.","ne":"युरोपको औद्योगिक क्रान्ति बाफ प्रविधिबाट अघि बढेको थियो।","fil":"Ang Rebolusyong Industriyal sa Europa ay itinulak ng teknolohiya ng singaw."},{"n":58,"en":"There is a welcome party for all new students each term.","ko":"매 학기 모든 신입생을 위한 환영 파티가 있다.","meta":["초빈출","핵심예측","보통"],"ceb":"Adunay welcome party alang sa tanang bag-ong estudyante matag termino.","ja":"毎学期、すべての新入生を対象とした歓迎会がある。","zh":"每学期都有面向所有新生的欢迎派对。","hi":"हर सत्र में सभी नए विद्यार्थियों के लिए स्वागत समारोह होता है।","es":"Cada período lectivo hay una fiesta de bienvenida para todos los estudiantes nuevos.","vi":"Mỗi học kỳ đều có một buổi tiệc chào đón tất cả sinh viên mới.","ne":"हरेक शैक्षिक सत्रमा सबै नयाँ विद्यार्थीका लागि स्वागत कार्यक्रम हुन्छ।","fil":"May salu-salo sa pagtanggap sa lahat ng bagong estudyante tuwing termino."},{"n":59,"en":"They developed a unique approach to training their employees.","ko":"그들은 직원들을 훈련하는 독특한 방법을 개발했다.","meta":["초빈출","보통"],"ceb":"Naghimo sila og talagsaong pamaagi sa pagbansay sa ilang mga empleyado.","ja":"彼らは従業員の訓練に独自の方法を開発した。","zh":"他们开发了一种独特的员工培训方法。","hi":"उन्होंने अपने कर्मचारियों को प्रशिक्षित करने का एक अनूठा तरीका विकसित किया।","es":"Desarrollaron un método único para formar a sus empleados.","vi":"Họ đã phát triển một phương pháp độc đáo để đào tạo nhân viên.","ne":"उनीहरूले आफ्ना कर्मचारीलाई तालिम दिने एउटा अनौठो विधि विकास गरे।","fil":"Bumuo sila ng natatanging paraan ng pagsasanay sa kanilang mga empleyado."},{"n":60,"en":"All lectures and learning materials can be found on the internet.","ko":"모든 강의와 학습 자료는 인터넷에서 찾을 수 있다.","meta":["초빈출","보통"],"ceb":"Ang tanang lektyur ug materyales sa pagkat-on makita sa internet.","ja":"すべての講義と学習資料はインターネットで見つけられる。","zh":"所有讲座和学习资料都可以在网上找到。","hi":"सभी व्याख्यान और अध्ययन सामग्री इंटरनेट पर मिल सकती है।","es":"Todas las clases y los materiales de aprendizaje se pueden encontrar en internet.","vi":"Tất cả bài giảng và tài liệu học tập đều có thể tìm thấy trên internet.","ne":"सबै व्याख्यान र अध्ययन सामग्री इन्टरनेटमा पाउन सकिन्छ।","fil":"Makikita sa internet ang lahat ng lektura at materyales sa pag-aaral."},{"n":61,"en":"Experts are now able to forecast weather over much longer periods.","ko":"전문가들은 이제 훨씬 더 장기간의 날씨를 예측할 수 있다.","meta":["초빈출","핵심예측","보통"],"ceb":"Ang mga eksperto karon makatagna sa panahon sa mas taas nga yugto.","ja":"専門家は現在、はるかに長期間の天気を予測できる。","zh":"专家现在能够预测更长时间范围内的天气。","hi":"विशेषज्ञ अब कहीं अधिक लंबी अवधि के लिए मौसम का पूर्वानुमान लगा सकते हैं।","es":"Los expertos ya pueden pronosticar el tiempo con mucha más antelación.","vi":"Các chuyên gia hiện có thể dự báo thời tiết trong những khoảng thời gian dài hơn nhiều.","ne":"विशेषज्ञहरू अब धेरै लामो अवधिका लागि मौसमको पूर्वानुमान गर्न सक्छन्।","fil":"Kaya na ngayon ng mga eksperto na magtaya ng panahon para sa mas mahahabang yugto."},{"n":62,"en":"Making mistakes is fine as long as you learn from them.","ko":"실수로부터 배운다면 실수를 해도 괜찮다.","meta":["초빈출","핵심예측","쉬움"],"ceb":"Okay ra ang masayop basta makat-on ka gikan niini.","ja":"失敗から学ぶ限り、失敗しても構わない。","zh":"只要能从错误中学习，犯错也没关系。","hi":"गलतियाँ करना ठीक है, बशर्ते आप उनसे सीखें।","es":"Cometer errores está bien siempre que aprendas de ellos.","vi":"Mắc lỗi không sao miễn là bạn học được từ những lỗi đó.","ne":"गल्तीबाट सिक्नुहुन्छ भने गल्ती गर्नु ठीकै हो।","fil":"Ayos lang magkamali basta natututo ka mula sa iyong mga pagkakamali."},{"n":63,"en":"Our courses help improve critical thinking and independent learning skills.","ko":"우리의 과정은 비판적 사고와 자기 주도 학습 능력을 향상하는 데 도움이 된다.","meta":["초빈출","핵심예측","어려움"],"ceb":"Ang among mga kurso makatabang sa kritikal nga panghunahuna ug independente nga pagkat-on.","ja":"私たちの講座は批判的思考力と自律的な学習能力の向上に役立つ。","zh":"我们的课程有助于提高批判性思维和独立学习技能。","hi":"हमारे पाठ्यक्रम आलोचनात्मक सोच और स्वतंत्र अध्ययन के कौशल को बेहतर बनाने में मदद करते हैं।","es":"Nuestros cursos ayudan a mejorar el pensamiento crítico y las habilidades de aprendizaje autónomo.","vi":"Các khóa học của chúng tôi giúp cải thiện tư duy phản biện và kỹ năng học tập độc lập.","ne":"हाम्रा पाठ्यक्रमले आलोचनात्मक सोच र स्वतन्त्र सिकाइका सीप सुधार्न मद्दत गर्छन्।","fil":"Tumutulong ang aming mga kurso na pagbutihin ang kritikal na pag-iisip at mga kasanayan sa malayang pag-aaral."},{"n":64,"en":"This course provides the opportunity to get valuable industry experience.","ko":"이 과정은 귀중한 산업 현장 경험을 얻을 기회를 제공한다.","meta":["초빈출","핵심예측","보통"],"ceb":"Kini nga kurso naghatag og oportunidad nga makakuha og bililhong kasinatian sa industriya.","ja":"この講座は貴重な業界経験を得る機会を提供する。","zh":"这门课程提供获得宝贵行业经验的机会。","hi":"यह पाठ्यक्रम उद्योग में मूल्यवान अनुभव प्राप्त करने का अवसर देता है।","es":"Este curso ofrece la oportunidad de adquirir valiosa experiencia en el sector.","vi":"Khóa học này tạo cơ hội tích lũy kinh nghiệm quý giá trong ngành.","ne":"यस पाठ्यक्रमले उद्योगमा मूल्यवान् अनुभव प्राप्त गर्ने अवसर प्रदान गर्छ।","fil":"Nagbibigay ang kursong ito ng pagkakataong magkaroon ng mahalagang karanasan sa industriya."},{"n":65,"en":"Some people are motivated by competition, while others prefer to collaborate.","ko":"어떤 사람들은 경쟁에서 동기를 얻는 반면, 다른 사람들은 협력을 선호한다.","meta":["초빈출","핵심예측","어려움"],"ceb":"Ang ubang tawo madasig sa kompetisyon, samtang ang uban mas gusto nga magtinabangay.","ja":"競争に意欲を感じる人もいれば、協力を好む人もいる。","zh":"有些人受到竞争激励，另一些人则喜欢合作。","hi":"कुछ लोग प्रतिस्पर्धा से प्रेरित होते हैं, जबकि अन्य सहयोग करना पसंद करते हैं।","es":"A algunas personas las motiva la competencia, mientras que otras prefieren colaborar.","vi":"Một số người được thúc đẩy bởi sự cạnh tranh, trong khi những người khác thích hợp tác.","ne":"केही मानिस प्रतिस्पर्धाबाट प्रेरित हुन्छन् भने अरू सहकार्य गर्न रुचाउँछन्।","fil":"Ang ilang tao ay nahihikayat ng kompetisyon, samantalang mas gusto ng iba ang pagtutulungan."},{"n":66,"en":"Students are encouraged to monitor their own attendance.","ko":"학생들은 자신의 출석 상황을 스스로 확인하도록 권장된다.","meta":["초빈출","보통"],"ceb":"Giawhag ang mga estudyante nga bantayan ang ilang kaugalingong attendance.","ja":"学生は自分の出席状況を確認するよう奨励されている。","zh":"鼓励学生自行关注出勤情况。","hi":"विद्यार्थियों को अपनी उपस्थिति की स्वयं निगरानी करने के लिए प्रोत्साहित किया जाता है।","es":"Se anima a los estudiantes a controlar su propia asistencia.","vi":"Sinh viên được khuyến khích tự theo dõi việc đi học của mình.","ne":"विद्यार्थीहरूलाई आफ्नो उपस्थिति आफैँ निगरानी गर्न प्रोत्साहित गरिन्छ।","fil":"Hinihikayat ang mga estudyante na subaybayan ang sarili nilang pagdalo."},{"n":67,"en":"The economy is now showing the first sign of recovery.","ko":"경제는 이제 회복의 첫 징후를 보이고 있다.","meta":["초빈출","핵심예측","보통"],"ceb":"Ang ekonomiya nagpakita na sa unang timailhan sa pagkaayo.","ja":"経済は今、回復の最初の兆しを見せている。","zh":"经济目前正显现出复苏的初步迹象。","hi":"अर्थव्यवस्था अब सुधार का पहला संकेत दिखा रही है।","es":"La economía muestra ahora el primer signo de recuperación.","vi":"Nền kinh tế hiện đang cho thấy dấu hiệu phục hồi đầu tiên.","ne":"अर्थतन्त्रले अहिले सुधारको पहिलो सङ्केत देखाउँदै छ।","fil":"Nagpapakita na ngayon ang ekonomiya ng unang palatandaan ng pagbangon."},{"n":68,"en":"The plight of local wildlife has been ignored by developers.","ko":"지역 야생 동물이 처한 곤경은 개발업자들에게 무시되어 왔다.","meta":["초빈출","핵심예측","어려움"],"ceb":"Gibalewala sa mga developer ang kalisod sa lokal nga mga ihalas nga mananap.","ja":"地元の野生生物の苦境は開発業者に無視されてきた。","zh":"开发商忽视了当地野生动物的困境。","hi":"स्थानीय वन्यजीवों की दुर्दशा को विकासकर्ताओं ने नजरअंदाज किया है।","es":"Los promotores inmobiliarios han ignorado la difícil situación de la fauna local.","vi":"Các nhà phát triển đã phớt lờ tình cảnh khó khăn của động vật hoang dã địa phương.","ne":"स्थानीय वन्यजन्तुको दुर्दशालाई विकासकर्ताहरूले बेवास्ता गरेका छन्।","fil":"Binalewala ng mga tagapagpaunlad ang mahirap na kalagayan ng lokal na mga ligaw na hayop."},{"n":69,"en":"The site is designed to be highly interactive.","ko":"이 사이트는 상호작용이 활발하도록 설계되었다.","meta":["초빈출","핵심예측","쉬움"],"ceb":"Ang site gidisenyo aron mahimong interaktibo kaayo.","ja":"このサイトは双方向性が高くなるよう設計されている。","zh":"该网站被设计成具有高度互动性。","hi":"साइट को अत्यधिक संवादात्मक बनाने के लिए डिजाइन किया गया है।","es":"El sitio está diseñado para ser muy interactivo.","vi":"Trang web được thiết kế để có tính tương tác cao.","ne":"यो साइटलाई अत्यन्त अन्तरक्रियात्मक हुने गरी डिजाइन गरिएको छ।","fil":"Ang site ay idinisenyong maging lubhang interaktibo."},{"n":70,"en":"The lecture tomorrow will discuss the educational policy of the United States.","ko":"내일 강의에서는 미국의 교육 정책을 논의할 것이다.","meta":["초빈출","핵심예측","보통"],"ceb":"Ang lektyur ugma maghisgot sa polisiya sa edukasyon sa Estados Unidos.","ja":"明日の講義では米国の教育政策を取り上げる。","zh":"明天的讲座将讨论美国的教育政策。","hi":"कल के व्याख्यान में संयुक्त राज्य अमेरिका की शिक्षा नीति पर चर्चा होगी।","es":"La clase de mañana tratará sobre la política educativa de Estados Unidos.","vi":"Bài giảng ngày mai sẽ thảo luận về chính sách giáo dục của Hoa Kỳ.","ne":"भोलिको व्याख्यानमा संयुक्त राज्य अमेरिकाको शिक्षा नीतिबारे छलफल गरिनेछ।","fil":"Tatalakayin sa lektura bukas ang patakaran sa edukasyon ng Estados Unidos."},{"n":71,"en":"You should submit your term papers to the general office.","ko":"학기말 논문은 일반 사무실에 제출해야 한다.","meta":["초빈출","핵심예측","쉬움"],"ceb":"Kinahanglan nimo isumite ang imong term papers sa general office.","ja":"学期末レポートは総務事務室に提出すべきである。","zh":"你应该把学期论文提交到综合办公室。","hi":"आपको अपने सत्रांत शोधपत्र सामान्य कार्यालय में जमा करने चाहिए।","es":"Debes entregar tus trabajos de fin de período en la oficina general.","vi":"Bạn nên nộp bài luận cuối kỳ tại văn phòng chung.","ne":"तपाईंले आफ्ना सत्रान्त शोधपत्रहरू सामान्य कार्यालयमा बुझाउनुपर्छ।","fil":"Dapat mong isumite ang iyong mga papel sa pagtatapos ng termino sa pangkalahatang opisina."},{"n":72,"en":"Speed is defined as how quickly an object or a person moves.","ko":"속력은 물체나 사람이 얼마나 빠르게 움직이는지를 나타내는 것으로 정의된다.","meta":["초빈출","보통"],"ceb":"Ang speed gihubit isip kapaspas sa paglihok sa butang o tawo.","ja":"速さとは物体や人がどれほど速く移動するかを表すものである。","zh":"速度被定义为物体或人移动的快慢。","hi":"गति को इस आधार पर परिभाषित किया जाता है कि कोई वस्तु या व्यक्ति कितनी तेजी से चलता है।","es":"La velocidad se define como la rapidez con la que se mueve un objeto o una persona.","vi":"Tốc độ được định nghĩa là mức độ nhanh chậm khi một vật hoặc một người di chuyển.","ne":"कुनै वस्तु वा व्यक्ति कति छिटो चल्छ भन्ने आधारमा गति परिभाषित गरिन्छ।","fil":"Ang bilis ay tinutukoy bilang kung gaano kabilis gumagalaw ang isang bagay o tao."},{"n":73,"en":"Make sure you choose a course that provides great career opportunities.","ko":"좋은 취업 기회를 제공하는 과정을 선택하도록 하세요.","meta":["초빈출","핵심예측","보통"],"ceb":"Siguroha nga mopili ka og kurso nga adunay maayong oportunidad sa karera.","ja":"優れた就職の機会を提供する講座を選ぶようにしてください。","zh":"务必选择一门能提供良好职业机会的课程。","hi":"सुनिश्चित करें कि आप ऐसा पाठ्यक्रम चुनें जो करियर के अच्छे अवसर प्रदान करे।","es":"Asegúrate de elegir un curso que ofrezca excelentes oportunidades profesionales.","vi":"Hãy chắc chắn chọn khóa học mang lại những cơ hội nghề nghiệp tốt.","ne":"उत्कृष्ट करियर अवसर दिने पाठ्यक्रम छनोट गर्न निश्चित गर्नुहोस्।","fil":"Tiyaking pumili ng kursong nagbibigay ng magagandang oportunidad sa karera."},{"n":74,"en":"We no longer respond to any post reference requests.","ko":"우리는 더 이상 어떠한 후속 추천서 요청에도 응답하지 않는다.","meta":["초빈출","핵심예측","보통"],"ceb":"Dili na kami motubag sa bisan unsang hangyo sa reference pinaagi sa koreo.","ja":"私たちは郵送による推薦状の依頼にはもう応じない。","zh":"我们不再回复任何事后推荐请求。","hi":"अब हम बाद में संदर्भ माँगने वाले किसी भी अनुरोध का उत्तर नहीं देते।","es":"Ya no respondemos a solicitudes de referencias posteriores.","vi":"Chúng tôi không còn phản hồi bất kỳ yêu cầu cung cấp tài liệu tham khảo nào sau đó.","ne":"हामी अब पछि गरिने कुनै पनि सन्दर्भ अनुरोधको जवाफ दिँदैनौँ।","fil":"Hindi na kami tumutugon sa anumang kahilingan para sa sanggunian pagkatapos nito."},{"n":75,"en":"Sugar is a compound including carbon, oxygen, and hydrogen atoms.","ko":"설탕은 탄소, 산소, 수소 원자를 포함하는 화합물이다.","meta":["초빈출","핵심예측","어려움"],"ceb":"Ang asukar usa ka compound nga adunay mga atomo sa carbon, oxygen ug hydrogen.","ja":"砂糖は炭素、酸素、水素の原子を含む化合物である。","zh":"糖是由碳、氧和氢原子组成的化合物。","hi":"चीनी एक यौगिक है जिसमें कार्बन, ऑक्सीजन और हाइड्रोजन के परमाणु होते हैं।","es":"El azúcar es un compuesto que contiene átomos de carbono, oxígeno e hidrógeno.","vi":"Đường là một hợp chất chứa các nguyên tử cacbon, oxy và hydro.","ne":"चिनी कार्बन, अक्सिजन र हाइड्रोजनका परमाणु भएको यौगिक हो।","fil":"Ang asukal ay isang compound na naglalaman ng mga atomo ng carbon, oxygen at hydrogen."},{"n":76,"en":"It is necessary to dress formally for the graduation ceremony.","ko":"졸업식에는 정장을 입어야 한다.","meta":["초빈출","핵심예측","보통"],"ceb":"Kinahanglan magsul-ob og pormal alang sa seremonya sa graduation.","ja":"卒業式には正装する必要がある。","zh":"参加毕业典礼必须穿着正式服装。","hi":"स्नातक समारोह के लिए औपचारिक पोशाक पहनना आवश्यक है।","es":"Es necesario vestir formalmente para la ceremonia de graduación.","vi":"Cần ăn mặc trang trọng khi tham dự lễ tốt nghiệp.","ne":"दीक्षान्त समारोहका लागि औपचारिक पोसाक लगाउनु आवश्यक छ।","fil":"Kailangang magsuot ng pormal na damit para sa seremonya ng pagtatapos."},{"n":77,"en":"A series of lectures showcasing economic research have been recorded.","ko":"경제 연구를 소개하는 일련의 강의가 녹화되었다.","meta":["초빈출","핵심예측","보통"],"ceb":"Narekord ang serye sa mga lektyur nga nagpakita sa panukiduki sa ekonomiya.","ja":"経済研究を紹介する一連の講義が録画された。","zh":"一系列展示经济研究的讲座已经被录制下来。","hi":"आर्थिक शोध को प्रस्तुत करने वाले व्याख्यानों की एक श्रृंखला रिकॉर्ड की गई है।","es":"Se ha grabado una serie de conferencias que presentan investigaciones económicas.","vi":"Một loạt bài giảng giới thiệu các nghiên cứu kinh tế đã được ghi lại.","ne":"आर्थिक अनुसन्धान प्रस्तुत गर्ने व्याख्यानहरूको शृङ्खला रेकर्ड गरिएको छ।","fil":"Naitala na ang serye ng mga lekturang nagtatampok ng pananaliksik sa ekonomiya."},{"n":78,"en":"Consumer confidence tends to increase as the economy expands.","ko":"경제가 성장함에 따라 소비자 신뢰도는 높아지는 경향이 있다.","meta":["초빈출","핵심예측","어려움"],"ceb":"Ang pagsalig sa mga konsumidor kasagarang mosaka samtang molambo ang ekonomiya.","ja":"経済が拡大するにつれて消費者の信頼感は高まる傾向がある。","zh":"随着经济扩张，消费者信心往往会增强。","hi":"अर्थव्यवस्था के विस्तार के साथ उपभोक्ताओं का विश्वास बढ़ने की प्रवृत्ति होती है।","es":"La confianza del consumidor tiende a aumentar a medida que crece la economía.","vi":"Niềm tin của người tiêu dùng có xu hướng tăng khi nền kinh tế phát triển.","ne":"अर्थतन्त्र विस्तार हुँदै जाँदा उपभोक्ताको विश्वास बढ्ने प्रवृत्ति हुन्छ।","fil":"Malamang na tumaas ang tiwala ng mga mamimili habang lumalago ang ekonomiya."},{"n":79,"en":"Food containing ample calories provides little or no nutritional value.","ko":"열량이 많은 식품은 영양가가 거의 없거나 전혀 없다.","meta":["초빈출","핵심예측","어려움"],"ceb":"Ang pagkaon nga daghan og kaloriya adunay gamay o walay sustansiya.","ja":"カロリーが豊富な食品には栄養価がほとんど、あるいは全くない。","zh":"含有大量热量的食物几乎没有营养价值。","hi":"बहुत अधिक कैलोरी वाले भोजन में बहुत कम या कोई पोषण मूल्य नहीं होता।","es":"Los alimentos que contienen abundantes calorías aportan poco o ningún valor nutricional.","vi":"Thực phẩm chứa nhiều calo có ít hoặc không có giá trị dinh dưỡng.","ne":"प्रशस्त क्यालोरी भएको खानामा थोरै वा कुनै पोषण मूल्य हुँदैन।","fil":"Ang pagkaing maraming calorie ay may kaunti o walang halagang nutrisyonal."},{"n":80,"en":"Many vocational courses at institutions are funded by private enterprises.","ko":"교육 기관의 많은 직업 교육 과정은 민간 기업의 자금 지원을 받는다.","meta":["초빈출","핵심예측","어려움"],"ceb":"Daghang vocational course sa mga institusyon ang gipondohan sa pribadong negosyo.","ja":"教育機関の多くの職業訓練講座は民間企業から資金提供を受けている。","zh":"教育机构的许多职业课程由私营企业资助。","hi":"संस्थानों में अनेक व्यावसायिक पाठ्यक्रमों को निजी उद्यमों द्वारा वित्तपोषित किया जाता है।","es":"Muchos cursos de formación profesional en instituciones son financiados por empresas privadas.","vi":"Nhiều khóa đào tạo nghề tại các cơ sở được các doanh nghiệp tư nhân tài trợ.","ne":"संस्थाहरूका धेरै व्यावसायिक पाठ्यक्रमलाई निजी उद्यमहरूले आर्थिक सहयोग गर्छन्।","fil":"Maraming kursong bokasyonal sa mga institusyon ang pinopondohan ng mga pribadong negosyo."},{"n":81,"en":"The history department is very active in research.","ko":"역사학과는 연구 활동에 매우 적극적이다.","meta":["초빈출","핵심예측","보통"],"ceb":"Aktibo kaayo ang departamento sa kasaysayan sa panukiduki.","ja":"歴史学科は研究活動が非常に盛んである。","zh":"历史系在研究方面非常活跃。","hi":"इतिहास विभाग शोध में बहुत सक्रिय है।","es":"El departamento de historia es muy activo en la investigación.","vi":"Khoa lịch sử rất tích cực trong nghiên cứu.","ne":"इतिहास विभाग अनुसन्धानमा धेरै सक्रिय छ।","fil":"Napakaaktibo ng departamento ng kasaysayan sa pananaliksik."},{"n":82,"en":"The opening hours of the library are reduced during summer.","ko":"여름 동안 도서관 운영 시간이 단축된다.","meta":["초빈출","핵심예측","보통"],"ceb":"Gipamubo ang oras sa pag-abli sa librarya panahon sa ting-init.","ja":"夏の間、図書館の開館時間は短縮される。","zh":"图书馆在夏季缩短开放时间。","hi":"गर्मियों के दौरान पुस्तकालय के खुलने का समय कम कर दिया जाता है।","es":"El horario de apertura de la biblioteca se reduce durante el verano.","vi":"Giờ mở cửa của thư viện được rút ngắn vào mùa hè.","ne":"गर्मीको समयमा पुस्तकालय खुल्ने अवधि घटाइन्छ।","fil":"Umiikli ang oras ng pagbubukas ng aklatan sa tag-init."},{"n":83,"en":"Measures must be taken to prevent the unemployment rate from increasing.","ko":"실업률이 증가하는 것을 막기 위한 조치를 취해야 한다.","meta":["초빈출","핵심예측","어려움"],"ceb":"Kinahanglan mohimo og mga lakang aron mapugngan ang pagsaka sa unemployment rate.","ja":"失業率の上昇を防ぐための対策を講じなければならない。","zh":"必须采取措施防止失业率上升。","hi":"बेरोजगारी दर को बढ़ने से रोकने के लिए उपाय किए जाने चाहिए।","es":"Deben tomarse medidas para evitar que aumente la tasa de desempleo.","vi":"Cần thực hiện các biện pháp để ngăn tỷ lệ thất nghiệp gia tăng.","ne":"बेरोजगारी दर बढ्न नदिन उपायहरू अपनाउनुपर्छ।","fil":"Kailangang gumawa ng mga hakbang upang mapigilan ang pagtaas ng antas ng kawalan ng trabaho."},{"n":84,"en":"Journalism faces the crisis in the light of the digital revolution.","ko":"언론은 디지털 혁명으로 인해 위기에 직면해 있다.","meta":["초빈출","핵심예측","어려움"],"ceb":"Ang journalism nag-atubang og krisis tungod sa digital revolution.","ja":"デジタル革命を背景にジャーナリズムは危機に直面している。","zh":"面对数字革命，新闻业面临危机。","hi":"डिजिटल क्रांति के चलते पत्रकारिता संकट का सामना कर रही है।","es":"El periodismo se enfrenta a una crisis ante la revolución digital.","vi":"Ngành báo chí đang đối mặt với khủng hoảng trước cuộc cách mạng kỹ thuật số.","ne":"डिजिटल क्रान्तिका कारण पत्रकारिताले सङ्कटको सामना गरिरहेको छ।","fil":"Nahaharap ang pamamahayag sa krisis dahil sa digital na rebolusyon."},{"n":85,"en":"It takes a long time to walk to university.","ko":"대학까지 걸어가는 데 오랜 시간이 걸린다.","meta":["초빈출","쉬움"],"ceb":"Dugay ang pagbaktas padulong sa unibersidad.","ja":"大学まで歩くには長い時間がかかる。","zh":"步行去大学需要很长时间。","hi":"विश्वविद्यालय तक पैदल जाने में बहुत समय लगता है।","es":"Se tarda mucho en llegar a pie a la universidad.","vi":"Đi bộ đến trường đại học mất nhiều thời gian.","ne":"विश्वविद्यालयसम्म पैदल जान धेरै समय लाग्छ।","fil":"Matagal ang paglalakad papuntang unibersidad."},{"n":86,"en":"The news will not be received until the following week.","ko":"그 소식은 다음 주가 되어서야 전달될 것이다.","meta":["초빈출","보통"],"ceb":"Ang balita dili madawat hangtod sa sunod semana.","ja":"その知らせが届くのは翌週になってからだ。","zh":"直到下周才会收到消息。","hi":"अगले सप्ताह तक समाचार प्राप्त नहीं होगा।","es":"La noticia no se recibirá hasta la semana siguiente.","vi":"Phải đến tuần sau nữa mới nhận được tin tức.","ne":"अर्को हप्तासम्म समाचार प्राप्त हुने छैन।","fil":"Hindi matatanggap ang balita hanggang sa susunod na linggo."},{"n":87,"en":"A mixture is defined as a compound of chemically separate parts.","ko":"혼합물은 화학적으로 분리된 부분들의 결합으로 정의된다.","meta":["초빈출","어려움"],"ceb":"Ang mixture gihubit isip compound sa mga bahin nga bulag sa kemikal nga paagi.","ja":"混合物は化学的に分離した部分からなる化合物と定義される。","zh":"混合物被定义为由化学上相互独立的部分组成的组合物。","hi":"मिश्रण को रासायनिक रूप से अलग भागों के संयोजन के रूप में परिभाषित किया जाता है।","es":"Una mezcla se define como un conjunto de partes químicamente separadas.","vi":"Hỗn hợp được định nghĩa là một tổ hợp gồm các thành phần tách biệt về mặt hóa học.","ne":"मिश्रणलाई रासायनिक रूपमा अलग भागहरूको संयोजनका रूपमा परिभाषित गरिन्छ।","fil":"Ang halo ay tinutukoy bilang isang pinagsamang bagay na binubuo ng mga bahaging magkakahiwalay sa kemikal na paraan."},{"n":88,"en":"Many food crops require large amounts of water and fertilizer.","ko":"많은 식량 작물에는 다량의 물과 비료가 필요하다.","meta":["초빈출","핵심예측","어려움"],"ceb":"Daghang tanom nga pagkaon nagkinahanglan og daghang tubig ug abono.","ja":"多くの食用作物は大量の水と肥料を必要とする。","zh":"许多粮食作物需要大量水和肥料。","hi":"कई खाद्य फसलों को बड़ी मात्रा में पानी और उर्वरक की आवश्यकता होती है।","es":"Muchos cultivos alimentarios requieren grandes cantidades de agua y fertilizantes.","vi":"Nhiều cây lương thực cần lượng lớn nước và phân bón.","ne":"धेरै खाद्यान्न बालीलाई ठूलो मात्रामा पानी र मल आवश्यक पर्छ।","fil":"Maraming pananim na pagkain ang nangangailangan ng malaking dami ng tubig at pataba."},{"n":89,"en":"New developments in manufacturing are changing the way we live.","ko":"제조업의 새로운 발전은 우리의 생활 방식을 바꾸고 있다.","meta":["초빈출","핵심예측","보통"],"ceb":"Ang bag-ong mga kalamboan sa manufacturing nag-usab sa atong paagi sa pagkinabuhi.","ja":"製造業の新たな発展は私たちの生活様式を変えている。","zh":"制造业的新发展正在改变我们的生活方式。","hi":"विनिर्माण में नए विकास हमारे जीवन जीने के तरीके को बदल रहे हैं।","es":"Los nuevos avances en la fabricación están cambiando nuestra forma de vivir.","vi":"Những tiến bộ mới trong sản xuất đang thay đổi cách chúng ta sống.","ne":"उत्पादन क्षेत्रमा भएका नयाँ विकासले हाम्रो जीवनशैली बदलिरहेका छन्।","fil":"Binabago ng mga bagong pagsulong sa pagmamanupaktura ang ating paraan ng pamumuhay."},{"n":90,"en":"New materials and techniques are changing the style of modern architecture.","ko":"새로운 재료와 기술은 현대 건축의 양식을 바꾸고 있다.","meta":["초빈출","핵심예측","보통"],"ceb":"Ang bag-ong materyales ug teknik nag-usab sa estilo sa modernong arkitektura.","ja":"新しい材料と技術が現代建築の様式を変えている。","zh":"新材料和新技术正在改变现代建筑的风格。","hi":"नई सामग्रियाँ और तकनीकें आधुनिक वास्तुकला की शैली को बदल रही हैं।","es":"Los nuevos materiales y técnicas están cambiando el estilo de la arquitectura moderna.","vi":"Các vật liệu và kỹ thuật mới đang thay đổi phong cách kiến trúc hiện đại.","ne":"नयाँ सामग्री र प्रविधिले आधुनिक वास्तुकलाको शैली बदलिरहेका छन्।","fil":"Binabago ng mga bagong materyales at teknik ang estilo ng modernong arkitektura."},{"n":91,"en":"There will be a chemistry test in the class next week.","ko":"다음 주 수업에서 화학 시험이 있을 예정이다.","meta":["초빈출","핵심예측","쉬움"],"ceb":"Adunay chemistry test sa klase sunod semana.","ja":"来週の授業で化学の試験がある。","zh":"下周课堂上将有一场化学测试。","hi":"अगले सप्ताह कक्षा में रसायन विज्ञान की परीक्षा होगी।","es":"Habrá un examen de química en clase la próxima semana.","vi":"Tuần tới sẽ có bài kiểm tra hóa học trên lớp.","ne":"अर्को हप्ता कक्षामा रसायनशास्त्रको परीक्षा हुनेछ।","fil":"Magkakaroon ng pagsusulit sa kimika sa klase sa susunod na linggo."},{"n":92,"en":"Information technology has changed the way people study today.","ko":"정보 기술은 오늘날 사람들이 공부하는 방식을 변화시켰다.","meta":["초빈출","핵심예측","쉬움"],"ceb":"Ang information technology nakapausab sa paagi sa pagtuon sa mga tawo karon.","ja":"情報技術は今日の人々の学習方法を変えた。","zh":"信息技术改变了当今人们的学习方式。","hi":"सूचना प्रौद्योगिकी ने आज लोगों के अध्ययन करने के तरीके को बदल दिया है।","es":"La tecnología de la información ha cambiado la forma en que la gente estudia hoy.","vi":"Công nghệ thông tin đã thay đổi cách con người học tập ngày nay.","ne":"सूचना प्रविधिले आज मानिसहरूको अध्ययन गर्ने तरिका बदलिदिएको छ।","fil":"Binago ng teknolohiya ng impormasyon ang paraan ng pag-aaral ng mga tao ngayon."},{"n":93,"en":"The very basic feature of computing would be counting and calculating.","ko":"컴퓨팅의 가장 기본적인 특징은 수를 세고 계산하는 것이다.","meta":["초빈출","핵심예측","보통"],"ceb":"Ang labing sukaranang bahin sa computing mao ang pag-ihap ug pagkalkula.","ja":"コンピューティングの最も基本的な特徴は数えることと計算することだろう。","zh":"计算的最基本特征是计数和运算。","hi":"कंप्यूटिंग की सबसे बुनियादी विशेषता गिनना और गणना करना होगी।","es":"La característica más básica de la informática sería contar y calcular.","vi":"Đặc điểm cơ bản nhất của điện toán là đếm và tính toán.","ne":"कम्प्युटिङको सबैभन्दा आधारभूत विशेषता गन्नु र गणना गर्नु हो।","fil":"Ang pinakapayak na katangian ng computing ay pagbibilang at pagkalkula."},{"n":94,"en":"Farmers need to adapt to the changes in climate.","ko":"농부들은 기후 변화에 적응해야 한다.","meta":["초빈출","핵심예측","쉬움"],"ceb":"Ang mga mag-uuma kinahanglan mopasibo sa kausaban sa klima.","ja":"農家は気候の変化に適応する必要がある。","zh":"农民需要适应气候变化。","hi":"किसानों को जलवायु में होने वाले बदलावों के अनुरूप ढलना होगा।","es":"Los agricultores necesitan adaptarse a los cambios del clima.","vi":"Nông dân cần thích nghi với những thay đổi của khí hậu.","ne":"किसानहरूले जलवायु परिवर्तनअनुसार आफूलाई अनुकूल बनाउनुपर्छ।","fil":"Kailangang umangkop ang mga magsasaka sa mga pagbabago ng klima."},{"n":95,"en":"An effective business manager is always open to new ideas.","ko":"유능한 사업 관리자는 항상 새로운 아이디어를 받아들일 준비가 되어 있다.","meta":["초빈출","핵심예측","보통"],"ceb":"Ang epektibong manager sa negosyo kanunay bukas sa bag-ong mga ideya.","ja":"有能な経営者は常に新しい考えを受け入れる。","zh":"高效的商业管理者总是乐于接受新想法。","hi":"एक प्रभावी व्यवसाय प्रबंधक हमेशा नए विचारों के लिए खुला रहता है।","es":"Un gerente empresarial eficaz siempre está abierto a nuevas ideas.","vi":"Một nhà quản lý doanh nghiệp hiệu quả luôn cởi mở với những ý tưởng mới.","ne":"एक प्रभावकारी व्यवसाय व्यवस्थापक नयाँ विचारप्रति सधैँ खुला हुन्छ।","fil":"Ang isang mahusay na tagapamahala ng negosyo ay laging bukas sa mga bagong ideya."},{"n":96,"en":"There is an accounting assignment for finance students.","ko":"금융 전공 학생들에게 회계 과제가 있다.","meta":["초빈출","핵심예측","쉬움"],"ceb":"Adunay accounting assignment alang sa mga estudyante sa finance.","ja":"金融を学ぶ学生には会計の課題がある。","zh":"金融专业的学生有一项会计作业。","hi":"वित्त के विद्यार्थियों के लिए लेखांकन का एक असाइनमेंट है।","es":"Hay una tarea de contabilidad para los estudiantes de finanzas.","vi":"Có một bài tập kế toán dành cho sinh viên tài chính.","ne":"वित्तका विद्यार्थीहरूका लागि लेखासम्बन्धी एउटा असाइनमेन्ट छ।","fil":"May takdang-aralin sa accounting para sa mga estudyante ng pananalapi."},{"n":97,"en":"Linguistics is the scientific study and analysis of language.","ko":"언어학은 언어에 대한 과학적 연구와 분석이다.","meta":["초빈출","핵심예측","어려움"],"ceb":"Ang linguistics mao ang siyentipikong pagtuon ug pag-analisa sa pinulongan.","ja":"言語学は言語を科学的に研究し分析する学問である。","zh":"语言学是对语言进行科学研究和分析的学科。","hi":"भाषाविज्ञान भाषा का वैज्ञानिक अध्ययन और विश्लेषण है।","es":"La lingüística es el estudio y análisis científicos del lenguaje.","vi":"Ngôn ngữ học là nghiên cứu và phân tích ngôn ngữ một cách khoa học.","ne":"भाषाविज्ञान भाषाको वैज्ञानिक अध्ययन र विश्लेषण हो।","fil":"Ang lingguwistika ay ang siyentipikong pag-aaral at pagsusuri ng wika."},{"n":98,"en":"Practical experiments are a central part of the chemistry course.","ko":"실습 실험은 화학 과정의 핵심 부분이다.","meta":["초빈출","핵심예측","어려움"],"ceb":"Ang praktikal nga eksperimento sentral nga bahin sa kurso sa chemistry.","ja":"実験実習は化学講座の中心的な部分である。","zh":"实践实验是化学课程的核心部分。","hi":"व्यावहारिक प्रयोग रसायन विज्ञान पाठ्यक्रम का प्रमुख हिस्सा हैं।","es":"Los experimentos prácticos son una parte central del curso de química.","vi":"Các thí nghiệm thực hành là một phần trọng tâm của khóa học hóa học.","ne":"व्यावहारिक प्रयोगहरू रसायनशास्त्र पाठ्यक्रमका मुख्य भाग हुन्।","fil":"Ang mga praktikal na eksperimento ay pangunahing bahagi ng kurso sa kimika."},{"n":99,"en":"Extracurricular activities can help students develop new talents.","ko":"과외 활동은 학생들이 새로운 재능을 개발하는 데 도움이 될 수 있다.","meta":["초빈출","핵심예측","어려움"],"ceb":"Ang extracurricular activities makatabang sa mga estudyante sa pagpalambo og bag-ong talento.","ja":"課外活動は学生が新しい才能を伸ばすのに役立つ。","zh":"课外活动可以帮助学生发展新才能。","hi":"पाठ्येतर गतिविधियाँ विद्यार्थियों को नई प्रतिभाएँ विकसित करने में मदद कर सकती हैं।","es":"Las actividades extracurriculares pueden ayudar a los estudiantes a desarrollar nuevos talentos.","vi":"Các hoạt động ngoại khóa có thể giúp sinh viên phát triển tài năng mới.","ne":"अतिरिक्त क्रियाकलापले विद्यार्थीहरूलाई नयाँ प्रतिभा विकास गर्न मद्दत गर्न सक्छन्।","fil":"Makatutulong ang mga gawaing ekstrakurikular sa paglinang ng mga bagong talento ng mga estudyante."},{"n":100,"en":"Trees benefit the city by soaking up the rainwater that runs off the roads.","ko":"나무는 도로에서 흘러내리는 빗물을 흡수하여 도시에 이로움을 준다.","meta":["초빈출","핵심예측","어려움"],"ceb":"Ang mga kahoy makatabang sa siyudad pinaagi sa pagsuyop sa tubig sa ulan nga nag-agas gikan sa dalan.","ja":"樹木は道路から流れ出る雨水を吸収することで都市に恩恵をもたらす。","zh":"树木吸收从道路流下的雨水，从而使城市受益。","hi":"पेड़ सड़कों से बहकर आने वाले बारिश के पानी को सोखकर शहर को लाभ पहुँचाते हैं।","es":"Los árboles benefician a la ciudad al absorber el agua de lluvia que escurre de las carreteras.","vi":"Cây xanh có lợi cho thành phố bằng cách hấp thụ nước mưa chảy từ đường phố.","ne":"रूखहरूले सडकबाट बगेर आउने वर्षाको पानी सोसेर सहरलाई फाइदा पुर्‍याउँछन्।","fil":"Nakikinabang ang lungsod sa mga puno dahil sinisipsip nila ang tubig-ulan na umaagos mula sa mga kalsada."},{"n":101,"en":"New media journalism is an exciting area of study.","ko":"뉴미디어 저널리즘은 흥미로운 연구 분야이다.","meta":["초빈출","핵심예측","쉬움"],"ceb":"Ang journalism sa bag-ong media usa ka makapainteres nga natad sa pagtuon.","ja":"ニューメディア・ジャーナリズムは刺激的な研究分野である。","zh":"新媒体新闻学是一个令人兴奋的研究领域。","hi":"नए मीडिया की पत्रकारिता अध्ययन का एक रोमांचक क्षेत्र है।","es":"El periodismo de nuevos medios es un campo de estudio apasionante.","vi":"Báo chí truyền thông mới là một lĩnh vực nghiên cứu thú vị.","ne":"नयाँ मिडियाको पत्रकारिता अध्ययनको एउटा रोचक क्षेत्र हो।","fil":"Ang pamamahayag sa bagong media ay isang kapana-panabik na larangan ng pag-aaral."},{"n":102,"en":"Many diseases that were once serious have now been eradicated.","ko":"한때 심각했던 많은 질병이 이제는 근절되었다.","meta":["초빈출","핵심예측","어려움"],"ceb":"Daghang sakit nga seryoso kaniadto napuo na karon.","ja":"かつて深刻だった多くの病気は今では根絶されている。","zh":"许多曾经严重的疾病现已被消灭。","hi":"कई बीमारियाँ जो कभी गंभीर थीं, अब समाप्त कर दी गई हैं।","es":"Muchas enfermedades que antes eran graves han sido erradicadas.","vi":"Nhiều căn bệnh từng nghiêm trọng nay đã được xóa bỏ.","ne":"पहिले गम्भीर मानिएका धेरै रोगहरू अहिले उन्मूलन भइसकेका छन्।","fil":"Maraming sakit na dati ay malubha ang napuksa na ngayon."},{"n":103,"en":"The use of mobile phones is not permitted in the library.","ko":"도서관에서는 휴대전화 사용이 허용되지 않는다.","meta":["초빈출","핵심예측","쉬움"],"ceb":"Dili gitugotan ang paggamit og cellphone sa librarya.","ja":"図書館では携帯電話の使用が認められていない。","zh":"图书馆内不允许使用手机。","hi":"पुस्तकालय में मोबाइल फोन का उपयोग करने की अनुमति नहीं है।","es":"No se permite el uso de teléfonos móviles en la biblioteca.","vi":"Không được phép sử dụng điện thoại di động trong thư viện.","ne":"पुस्तकालयमा मोबाइल फोन प्रयोग गर्न अनुमति छैन।","fil":"Hindi pinapayagan ang paggamit ng mga mobile phone sa aklatan."},{"n":104,"en":"Statistically speaking, the likelihood of this result is extremely low.","ko":"통계적으로 말하면 이러한 결과가 나올 가능성은 매우 낮다.","meta":["초빈출","핵심예측","어려움"],"ceb":"Sa estadistikang panglantaw, ubos kaayo ang posibilidad niini nga resulta.","ja":"統計的に言えば、この結果が生じる可能性は極めて低い。","zh":"从统计学角度看，这种结果出现的可能性极低。","hi":"सांख्यिकीय दृष्टि से इस परिणाम की संभावना अत्यंत कम है।","es":"Estadísticamente, la probabilidad de este resultado es extremadamente baja.","vi":"Về mặt thống kê, khả năng xảy ra kết quả này cực kỳ thấp.","ne":"तथ्याङ्कीय दृष्टिले यस नतिजाको सम्भावना अत्यन्त कम छ।","fil":"Batay sa estadistika, napakababa ng posibilidad ng resultang ito."},{"n":105,"en":"The terms, illness and disease, are confusing despite clear differences.","ko":"질환(illness)과 질병(disease)은 명확한 차이에도 불구하고 혼동되는 용어이다.","meta":["초빈출","어려움"],"ceb":"Ang mga termino nga illness ug disease makalibog bisan klaro ang ilang kalainan.","ja":"illnessとdiseaseという用語は明確な違いがあるにもかかわらず紛らわしい。","zh":"尽管 illness 和 disease 有明显差别，这两个术语仍容易混淆。","hi":"अस्वस्थता और रोग के शब्द स्पष्ट अंतर के बावजूद भ्रमित करते हैं।","es":"Los términos dolencia y enfermedad resultan confusos pese a sus claras diferencias.","vi":"Hai thuật ngữ tình trạng ốm đau và bệnh tật dễ gây nhầm lẫn dù có sự khác biệt rõ ràng.","ne":"स्पष्ट भिन्नता हुँदाहुँदै पनि अस्वस्थता र रोग भन्ने शब्दहरूले भ्रम सिर्जना गर्छन्।","fil":"Nakakalito ang mga terminong karamdaman at sakit sa kabila ng malinaw nilang pagkakaiba."},{"n":106,"en":"The very basic definition of computing would be counting and calculating.","ko":"컴퓨팅의 가장 기본적인 정의는 수를 세고 계산하는 것이다.","meta":["초빈출","보통"],"ceb":"Ang labing sukaranang kahulugan sa computing mao ang pag-ihap ug pagkalkula.","ja":"コンピューティングの最も基本的な定義は数えることと計算することだろう。","zh":"计算的最基本定义是计数和运算。","hi":"कंप्यूटिंग की सबसे बुनियादी परिभाषा गिनना और गणना करना होगी।","es":"La definición más básica de la informática sería contar y calcular.","vi":"Định nghĩa cơ bản nhất của điện toán là đếm và tính toán.","ne":"कम्प्युटिङको सबैभन्दा आधारभूत परिभाषा गन्नु र गणना गर्नु हो।","fil":"Ang pinakapayak na kahulugan ng computing ay pagbibilang at pagkalkula."},{"n":107,"en":"He wrote poetry and plays as well as scientific papers.","ko":"그는 과학 논문뿐만 아니라 시와 희곡도 썼다.","meta":["초빈출","핵심예측","보통"],"ceb":"Nagsulat siya og mga balak ug dula ingon man mga siyentipikong papel.","ja":"彼は科学論文だけでなく詩や戯曲も書いた。","zh":"他除了写科学论文，还写诗歌和戏剧。","hi":"उन्होंने वैज्ञानिक शोधपत्रों के साथ-साथ कविताएँ और नाटक भी लिखे।","es":"Escribió poesía y obras de teatro, además de artículos científicos.","vi":"Ông viết thơ và kịch cũng như các bài báo khoa học.","ne":"उनले वैज्ञानिक शोधपत्रका साथै कविता र नाटक पनि लेखे।","fil":"Sumulat siya ng mga tula at dula pati na rin ng mga siyentipikong papel."},{"n":108,"en":"Industry experts will discuss job opportunities in an automated workforce.","ko":"업계 전문가들은 자동화된 노동 시장에서의 취업 기회를 논의할 것이다.","meta":["초빈출","어려움"],"ceb":"Ang mga eksperto sa industriya maghisgot sa mga oportunidad sa trabaho sa automated workforce.","ja":"業界の専門家は自動化された労働環境での雇用機会について議論する。","zh":"行业专家将讨论自动化劳动力环境中的就业机会。","hi":"उद्योग विशेषज्ञ स्वचालित कार्यबल में रोजगार के अवसरों पर चर्चा करेंगे।","es":"Los expertos del sector debatirán las oportunidades laborales en una fuerza laboral automatizada.","vi":"Các chuyên gia trong ngành sẽ thảo luận về cơ hội việc làm trong lực lượng lao động tự động hóa.","ne":"उद्योग विशेषज्ञहरूले स्वचालित कार्यबलमा रोजगारीका अवसरबारे छलफल गर्नेछन्।","fil":"Tatalakayin ng mga eksperto sa industriya ang mga oportunidad sa trabaho sa isang awtomatikong lakas-paggawa."},{"n":109,"en":"The economic predictions turned out to be incorrect.","ko":"경제 예측은 틀린 것으로 밝혀졌다.","meta":["초빈출","핵심예측","보통"],"ceb":"Napamatud-an nga sayop ang mga panagna sa ekonomiya.","ja":"経済予測は誤っていたことが判明した。","zh":"事实证明经济预测不正确。","hi":"आर्थिक पूर्वानुमान गलत साबित हुए।","es":"Las predicciones económicas resultaron incorrectas.","vi":"Những dự đoán kinh tế hóa ra không chính xác.","ne":"आर्थिक पूर्वानुमानहरू गलत साबित भए।","fil":"Lumabas na mali ang mga pagtatayang pang-ekonomiya."},{"n":110,"en":"Cells are the basic building blocks of all animals and plants.","ko":"세포는 모든 동물과 식물의 기본 구성 요소이다.","meta":["초빈출","핵심예측","보통"],"ceb":"Ang mga selula mao ang sukaranang mga bahin sa tanang mananap ug tanom.","ja":"細胞はすべての動植物の基本的な構成単位である。","zh":"细胞是所有动植物的基本构成单位。","hi":"कोशिकाएँ सभी पशुओं और पौधों की मूल संरचनात्मक इकाइयाँ हैं।","es":"Las células son los componentes básicos de todos los animales y plantas.","vi":"Tế bào là đơn vị cấu tạo cơ bản của mọi động vật và thực vật.","ne":"कोशिकाहरू सबै जनावर र वनस्पतिका आधारभूत संरचनात्मक एकाइ हुन्।","fil":"Ang mga selula ang pangunahing yunit na bumubuo sa lahat ng hayop at halaman."},{"n":111,"en":"Good nutrition is crucial to general health and vitality.","ko":"좋은 영양 상태는 전반적인 건강과 활력에 매우 중요하다.","meta":["초빈출","핵심예측","어려움"],"ceb":"Importante kaayo ang maayong nutrisyon sa kinatibuk-ang kahimsog ug kalagsik.","ja":"良好な栄養は全般的な健康と活力に不可欠である。","zh":"良好的营养对整体健康和活力至关重要。","hi":"अच्छा पोषण समग्र स्वास्थ्य और स्फूर्ति के लिए अत्यंत महत्वपूर्ण है।","es":"Una buena nutrición es fundamental para la salud general y la vitalidad.","vi":"Dinh dưỡng tốt rất quan trọng đối với sức khỏe tổng thể và sức sống.","ne":"राम्रो पोषण समग्र स्वास्थ्य र स्फूर्तिका लागि अत्यन्त महत्त्वपूर्ण छ।","fil":"Mahalaga ang mahusay na nutrisyon sa pangkalahatang kalusugan at sigla."},{"n":112,"en":"Parents are financially responsible for their children right up until they reach adulthood.","ko":"부모는 자녀가 성인이 될 때까지 경제적 책임을 진다.","meta":["초빈출","핵심예측","어려움"],"ceb":"Ang mga ginikanan responsable sa pinansiyal nga panginahanglan sa ilang mga anak hangtod nga mahamtong sila.","ja":"親は子供が成人するまで経済的責任を負う。","zh":"父母在经济上对孩子负有责任，直到他们成年。","hi":"माता-पिता अपने बच्चों के वयस्क होने तक उनकी आर्थिक जिम्मेदारी उठाते हैं।","es":"Los padres son responsables económicamente de sus hijos hasta que alcanzan la edad adulta.","vi":"Cha mẹ chịu trách nhiệm tài chính cho con cái cho đến khi chúng trưởng thành.","ne":"आमाबाबु आफ्ना छोराछोरी वयस्क नहुन्जेल उनीहरूको आर्थिक जिम्मेवारी वहन गर्छन्।","fil":"Pananagutan ng mga magulang ang gastusin ng kanilang mga anak hanggang sa umabot ang mga ito sa hustong gulang."},{"n":113,"en":"A world expert in financial management will give a guest lecture.","ko":"세계적인 재무 관리 전문가가 초청 강연을 할 것이다.","meta":["초빈출","핵심예측","어려움"],"ceb":"Usa ka eksperto sa tibuok kalibotan sa financial management mohatag og guest lecture.","ja":"財務管理の世界的専門家が特別講義を行う。","zh":"一位财务管理领域的世界级专家将进行客座讲座。","hi":"वित्तीय प्रबंधन के एक विश्वस्तरीय विशेषज्ञ अतिथि व्याख्यान देंगे।","es":"Un experto mundial en gestión financiera dará una conferencia como invitado.","vi":"Một chuyên gia hàng đầu thế giới về quản lý tài chính sẽ có bài giảng với tư cách khách mời.","ne":"वित्तीय व्यवस्थापनका एक विश्वस्तरीय विशेषज्ञले अतिथि व्याख्यान दिनेछन्।","fil":"Magbibigay ng panauhing lektura ang isang pandaigdigang eksperto sa pamamahala ng pananalapi."},{"n":114,"en":"A world-renowned expert on economics and marketing will give a lecture.","ko":"세계적으로 유명한 경제학 및 마케팅 전문가가 강연을 할 것이다.","meta":["초빈출","어려움"],"ceb":"Usa ka bantog sa kalibotang eksperto sa ekonomiya ug marketing mohatag og lektyur.","ja":"経済学とマーケティングの世界的に著名な専門家が講義を行う。","zh":"一位世界知名的经济学和市场营销专家将举行讲座。","hi":"अर्थशास्त्र और विपणन के एक विश्वप्रसिद्ध विशेषज्ञ व्याख्यान देंगे।","es":"Un experto de fama mundial en economía y marketing dará una conferencia.","vi":"Một chuyên gia nổi tiếng thế giới về kinh tế và tiếp thị sẽ có bài giảng.","ne":"अर्थशास्त्र र बजारीकरणका एक विश्वप्रसिद्ध विशेषज्ञले व्याख्यान दिनेछन्।","fil":"Magbibigay ng lektura ang isang kilalang eksperto sa buong mundo sa ekonomiya at marketing."},{"n":115,"en":"Advanced technology created growth in the economy.","ko":"첨단 기술은 경제 성장을 이끌었다.","meta":["초빈출","쉬움"],"ceb":"Ang abanteng teknolohiya nakapahinabo og pagtubo sa ekonomiya.","ja":"先進技術は経済成長をもたらした。","zh":"先进技术推动了经济增长。","hi":"उन्नत प्रौद्योगिकी ने अर्थव्यवस्था में वृद्धि पैदा की।","es":"La tecnología avanzada generó crecimiento económico.","vi":"Công nghệ tiên tiến đã tạo ra tăng trưởng kinh tế.","ne":"उन्नत प्रविधिले अर्थतन्त्रमा वृद्धि सिर्जना गर्‍यो।","fil":"Nagdulot ng paglago sa ekonomiya ang makabagong teknolohiya."},{"n":116,"en":"This course places considerable emphasis on critical thinking skills.","ko":"이 과정은 비판적 사고 능력을 상당히 강조한다.","meta":["초빈출","핵심예측","어려움"],"ceb":"Kini nga kurso naghatag og dakong gibug-aton sa kritikal nga panghunahuna.","ja":"この講座は批判的思考力を非常に重視している。","zh":"这门课程非常重视批判性思维技能。","hi":"यह पाठ्यक्रम आलोचनात्मक सोच के कौशल पर काफी जोर देता है।","es":"Este curso pone considerable énfasis en las habilidades de pensamiento crítico.","vi":"Khóa học này rất chú trọng kỹ năng tư duy phản biện.","ne":"यस पाठ्यक्रमले आलोचनात्मक सोचका सीपमा निकै जोड दिन्छ।","fil":"Malaking diin ang ibinibigay ng kursong ito sa mga kasanayan sa kritikal na pag-iisip."},{"n":117,"en":"A typical part of the course involves the study of society.","ko":"이 과정의 대표적인 부분에는 사회에 대한 연구가 포함된다.","meta":["초빈출","핵심예측","보통"],"ceb":"Ang kasagarang bahin sa kurso naglakip sa pagtuon sa katilingban.","ja":"この講座の典型的な内容には社会の研究が含まれる。","zh":"课程的一个典型部分涉及对社会的研究。","hi":"पाठ्यक्रम के एक सामान्य हिस्से में समाज का अध्ययन शामिल है।","es":"Una parte habitual del curso consiste en estudiar la sociedad.","vi":"Một phần điển hình của khóa học liên quan đến việc nghiên cứu xã hội.","ne":"पाठ्यक्रमको एउटा सामान्य भागमा समाजको अध्ययन समावेश छ।","fil":"Karaniwang bahagi ng kurso ang pag-aaral ng lipunan."},{"n":118,"en":"Banks charge interest on the money they lend to customers.","ko":"은행은 고객에게 빌려준 돈에 대해 이자를 부과한다.","meta":["초빈출","핵심예측","보통"],"ceb":"Ang mga bangko maningil og interes sa kuwarta nga ilang ipahulam sa mga kustomer.","ja":"銀行は顧客に貸した資金に利息を課す。","zh":"银行对借给客户的钱收取利息。","hi":"बैंक ग्राहकों को उधार दिए गए धन पर ब्याज लेते हैं।","es":"Los bancos cobran intereses por el dinero que prestan a sus clientes.","vi":"Các ngân hàng tính lãi trên số tiền họ cho khách hàng vay.","ne":"बैंकहरूले ग्राहकलाई ऋण दिएको रकममा ब्याज लिन्छन्।","fil":"Naniningil ng interes ang mga bangko sa perang ipinahihiram nila sa mga kliyente."},{"n":119,"en":"When launching a product, investigating and marketing are very crucial.","ko":"제품을 출시할 때 조사와 마케팅은 매우 중요하다.","meta":["초빈출","핵심예측","보통"],"ceb":"Sa paglunsad og produkto, importante kaayo ang pagsusi ug marketing.","ja":"製品を発売する際には調査とマーケティングが非常に重要である。","zh":"推出产品时，调查研究和市场营销至关重要。","hi":"किसी उत्पाद को बाजार में उतारते समय जाँच-पड़ताल और विपणन बेहद महत्वपूर्ण होते हैं।","es":"Al lanzar un producto, la investigación y el marketing son cruciales.","vi":"Khi ra mắt sản phẩm, nghiên cứu và tiếp thị là vô cùng quan trọng.","ne":"कुनै उत्पादन बजारमा ल्याउँदा अनुसन्धान र बजारीकरण अत्यन्त महत्त्वपूर्ण हुन्छन्।","fil":"Sa paglulunsad ng produkto, napakahalaga ng pagsisiyasat at marketing."},{"n":120,"en":"Scientists have founded all parts of society today.","ko":"과학자들은 오늘날 사회의 모든 부분을 구축해 왔다.","meta":["초빈출","핵심예측","쉬움"],"ceb":"Ang mga siyentista nagtukod sa tanang bahin sa katilingban karon.","ja":"科学者たちは今日の社会のあらゆる部分を築いてきた。","zh":"科学家奠定了当今社会各个部分的基础。","hi":"वैज्ञानिकों ने आज के समाज के सभी हिस्सों की नींव रखी है।","es":"Los científicos han fundado todas las partes de la sociedad actual.","vi":"Các nhà khoa học đã đặt nền móng cho mọi bộ phận của xã hội ngày nay.","ne":"वैज्ञानिकहरूले आजको समाजका सबै भागको जग बसालेका छन्।","fil":"Itinatag ng mga siyentipiko ang lahat ng bahagi ng lipunan ngayon."},{"n":121,"en":"Practical experience is a vital part of legal training.","ko":"실무 경험은 법률 교육의 필수적인 부분이다.","meta":["초빈출","쉬움"],"ceb":"Ang praktikal nga kasinatian usa ka mahinungdanong bahin sa pagbansay sa balaod.","ja":"実務経験は法律の訓練に不可欠な部分である。","zh":"实践经验是法律培训的重要组成部分。","hi":"व्यावहारिक अनुभव कानूनी प्रशिक्षण का महत्वपूर्ण हिस्सा है।","es":"La experiencia práctica es una parte vital de la formación jurídica.","vi":"Kinh nghiệm thực tế là một phần thiết yếu của đào tạo pháp luật.","ne":"व्यावहारिक अनुभव कानुनी तालिमको महत्त्वपूर्ण भाग हो।","fil":"Ang praktikal na karanasan ay mahalagang bahagi ng pagsasanay sa batas."},{"n":122,"en":"Recession triggers exciting creativity and high rates of public wisdom.","ko":"경기 침체는 흥미로운 창의성과 높은 수준의 대중적 지혜를 촉발한다.","meta":["초빈출","핵심예측","어려움"],"ceb":"Ang recession makapukaw og pagkamamugnaon ug taas nga lebel sa kaalam sa publiko.","ja":"不況は刺激的な創造性と高い水準の公共の知恵を引き起こす。","zh":"经济衰退激发出令人振奋的创造力和高度的公众智慧。","hi":"आर्थिक मंदी उत्साहजनक रचनात्मकता और जनसामान्य में उच्च स्तर की समझ को प्रेरित करती है।","es":"La recesión desencadena una creatividad estimulante y altos niveles de sabiduría pública.","vi":"Suy thoái kích thích sự sáng tạo đầy hứng khởi và mức độ hiểu biết cao trong công chúng.","ne":"आर्थिक मन्दीले उत्साहजनक सिर्जनशीलता र जनसाधारणमा उच्च स्तरको विवेक उत्पन्न गर्छ।","fil":"Nag-uudyok ang resesyon ng kapana-panabik na pagkamalikhain at mataas na antas ng karunungan ng publiko."},{"n":123,"en":"The history course is assessed via three written assignments.","ko":"역사 과정은 세 개의 서면 과제를 통해 평가된다.","meta":["초빈출","핵심예측","보통"],"ceb":"Ang kurso sa kasaysayan tasahon pinaagi sa tulo ka sinulat nga buluhaton.","ja":"歴史講座は三つの筆記課題によって評価される。","zh":"历史课程通过三项书面作业进行考核。","hi":"इतिहास पाठ्यक्रम का मूल्यांकन तीन लिखित असाइनमेंटों से किया जाता है।","es":"El curso de historia se evalúa mediante tres trabajos escritos.","vi":"Khóa học lịch sử được đánh giá thông qua ba bài tập viết.","ne":"इतिहास पाठ्यक्रमको मूल्याङ्कन तीनवटा लिखित असाइनमेन्टमार्फत गरिन्छ।","fil":"Tinatasa ang kurso sa kasaysayan sa pamamagitan ng tatlong nakasulat na takdang-aralin."},{"n":124,"en":"Students will focus on reporting news on changing the media world.","ko":"학생들은 미디어 세계의 변화에 관한 뉴스를 보도하는 데 집중할 것이다.","meta":["초빈출","핵심예측","보통"],"ceb":"Ang mga estudyante magpokus sa pagreport sa balita bahin sa nag-usab nga kalibotan sa media.","ja":"学生は変化するメディア界に関するニュース報道に重点を置く。","zh":"学生将重点关注有关媒体世界变化的新闻报道。","hi":"विद्यार्थी बदलते मीडिया जगत से संबंधित समाचारों की रिपोर्टिंग पर ध्यान देंगे।","es":"Los estudiantes se centrarán en informar sobre el cambiante mundo de los medios.","vi":"Sinh viên sẽ tập trung đưa tin về thế giới truyền thông đang thay đổi.","ne":"विद्यार्थीहरूले बदलिँदो मिडिया जगतसम्बन्धी समाचार सम्प्रेषणमा ध्यान दिनेछन्।","fil":"Magtutuon ang mga estudyante sa pagbabalita tungkol sa nagbabagong mundo ng media."},{"n":125,"en":"Studies showed there is a positive correlation between the two variables.","ko":"연구는 두 변수 사이에 양의 상관관계가 있음을 보여 주었다.","meta":["초빈출","핵심예측","어려움"],"ceb":"Gipakita sa mga pagtuon nga adunay positibong korelasyon tali sa duha ka variable.","ja":"研究によって二つの変数の間に正の相関があることが示された。","zh":"研究表明这两个变量之间存在正相关关系。","hi":"अध्ययनों से पता चला कि दोनों चरों के बीच सकारात्मक सहसंबंध है।","es":"Los estudios mostraron una correlación positiva entre las dos variables.","vi":"Các nghiên cứu cho thấy có mối tương quan thuận giữa hai biến số.","ne":"अध्ययनहरूले दुई चरबीच सकारात्मक सहसम्बन्ध रहेको देखाए।","fil":"Ipinakita ng mga pag-aaral na may positibong ugnayan sa pagitan ng dalawang variable."},{"n":126,"en":"We have sophisticated ways of studying the brain in action.","ko":"우리는 활동 중인 뇌를 연구하는 정교한 방법들을 가지고 있다.","meta":["초빈출","어려움"],"ceb":"Aduna kitay sopistikadong mga pamaagi sa pagtuon sa utok samtang naglihok kini.","ja":"私たちには活動中の脳を研究する高度な方法がある。","zh":"我们拥有研究大脑活动的先进方法。","hi":"हमारे पास सक्रिय मस्तिष्क का अध्ययन करने के उन्नत तरीके हैं।","es":"Disponemos de métodos sofisticados para estudiar el cerebro en funcionamiento.","vi":"Chúng ta có những phương pháp tinh vi để nghiên cứu não bộ khi đang hoạt động.","ne":"हामीसँग काम गरिरहेको मस्तिष्कको अध्ययन गर्ने उन्नत विधिहरू छन्।","fil":"Mayroon tayong mga sopistikadong paraan ng pag-aaral sa utak habang ito ay gumagana."},{"n":127,"en":"The dance department stages elaborate performances each semester.","ko":"무용학과는 매 학기 정교하게 준비된 공연을 무대에 올린다.","meta":["초빈출","어려움"],"ceb":"Ang departamento sa sayaw magpasundayag og detalyadong mga pasundayag matag semestre.","ja":"舞踊学科は毎学期、手の込んだ公演を行う。","zh":"舞蹈系每学期都举办精心制作的演出。","hi":"नृत्य विभाग हर सेमेस्टर विस्तृत और भव्य प्रस्तुतियाँ आयोजित करता है।","es":"El departamento de danza presenta espectáculos elaborados cada semestre.","vi":"Khoa múa tổ chức các buổi biểu diễn công phu mỗi học kỳ.","ne":"नृत्य विभागले प्रत्येक सेमेस्टरमा विस्तृत तयारीसहितका प्रस्तुतिहरू आयोजना गर्छ।","fil":"Nagtatanghal ang departamento ng sayaw ng masalimuot na pagtatanghal bawat semestre."},{"n":128,"en":"Student representatives will be visiting the classes with voting forms.","ko":"학생 대표들은 투표용지를 가지고 각 수업을 방문할 예정이다.","meta":["초빈출","핵심예측","어려움"],"ceb":"Ang mga representante sa estudyante mobisita sa mga klase dala ang mga pormas sa pagboto.","ja":"学生代表は投票用紙を持って各授業を訪問する予定である。","zh":"学生代表将携带投票表到各班访问。","hi":"छात्र प्रतिनिधि मतदान प्रपत्र लेकर कक्षाओं में जाएँगे।","es":"Los representantes estudiantiles visitarán las clases con formularios de votación.","vi":"Đại diện sinh viên sẽ đến các lớp học cùng với phiếu bầu.","ne":"विद्यार्थी प्रतिनिधिहरू मतदान फाराम लिएर कक्षाहरूमा जानेछन्।","fil":"Bibisitahin ng mga kinatawan ng estudyante ang mga klase na may dalang mga pormularyo sa pagboto."},{"n":129,"en":"In his lifetime, he composed a large number of works.","ko":"그는 평생에 걸쳐 수많은 작품을 창작했다.","meta":["초빈출","쉬움"],"ceb":"Sa iyang tibuok kinabuhi, nakakomposisyon siya og daghang obra.","ja":"彼は生涯にわたって数多くの作品を作曲した。","zh":"他一生中创作了大量作品。","hi":"उन्होंने अपने जीवनकाल में बड़ी संख्या में रचनाएँ कीं।","es":"A lo largo de su vida compuso un gran número de obras.","vi":"Trong suốt cuộc đời, ông đã sáng tác rất nhiều tác phẩm.","ne":"उनले आफ्नो जीवनकालमा धेरै रचनाहरू सिर्जना गरे।","fil":"Sa kanyang buhay, nakalikha siya ng napakaraming akda."},{"n":130,"en":"New media have transcended traditional national boundaries.","ko":"뉴미디어는 전통적인 국경을 초월해 왔다.","meta":["초빈출","보통"],"ceb":"Ang bag-ong media milapas sa tradisyonal nga mga utlanan sa nasod.","ja":"ニューメディアは従来の国境を越えてきた。","zh":"新媒体已经超越了传统的国界。","hi":"नए मीडिया ने पारंपरिक राष्ट्रीय सीमाओं को पार कर लिया है।","es":"Los nuevos medios han trascendido las fronteras nacionales tradicionales.","vi":"Truyền thông mới đã vượt qua các ranh giới quốc gia truyền thống.","ne":"नयाँ मिडियाले परम्परागत राष्ट्रिय सीमाहरू पार गरेको छ।","fil":"Nalampasan ng bagong media ang tradisyonal na mga hangganan ng bansa."},{"n":131,"en":"His analysis study appears to be based on the false premise.","ko":"그의 분석 연구는 잘못된 전제에 기반한 것으로 보인다.","meta":["초빈출","핵심예측","어려움"],"ceb":"Ang iyang analitikal nga pagtuon daw gibase sa sayop nga pangagpas.","ja":"彼の分析研究は誤った前提に基づいているようだ。","zh":"他的分析研究似乎建立在错误的前提上。","hi":"उनका विश्लेषणात्मक अध्ययन एक गलत धारणा पर आधारित प्रतीत होता है।","es":"Su estudio de análisis parece basarse en una premisa falsa.","vi":"Nghiên cứu phân tích của ông dường như dựa trên một tiền đề sai lầm.","ne":"उनको विश्लेषणात्मक अध्ययन गलत पूर्वधारणामा आधारित देखिन्छ।","fil":"Tila nakabatay sa maling palagay ang kanyang pag-aaral na analitikal."},{"n":132,"en":"Lectures are the oldest and the most formal teaching method at university.","ko":"강의는 대학에서 가장 오래되고 가장 공식적인 교수 방법이다.","meta":["초빈출","보통"],"ceb":"Ang mga lektyur mao ang labing karaan ug labing pormal nga pamaagi sa pagtudlo sa unibersidad.","ja":"講義は大学で最も古く、最も正式な教授方法である。","zh":"讲座是大学中最古老且最正式的教学方法。","hi":"विश्वविद्यालय में व्याख्यान शिक्षण का सबसे पुराना और सबसे औपचारिक तरीका है।","es":"Las clases magistrales son el método de enseñanza más antiguo y formal de la universidad.","vi":"Bài giảng là phương pháp giảng dạy lâu đời nhất và chính thức nhất ở đại học.","ne":"विश्वविद्यालयमा व्याख्यान सबैभन्दा पुरानो र सबैभन्दा औपचारिक शिक्षण विधि हो।","fil":"Ang mga lektura ang pinakamatanda at pinakapormal na pamamaraan ng pagtuturo sa unibersidad."},{"n":133,"en":"Research shows that exercising makes us feel better.","ko":"연구에 따르면 운동은 우리의 기분을 좋게 해 준다.","meta":["초빈출","쉬움"],"ceb":"Gipakita sa panukiduki nga ang pag-ehersisyo makapaayo sa atong pamati.","ja":"研究によると運動をすると気分が良くなる。","zh":"研究表明锻炼让我们感觉更好。","hi":"शोध से पता चलता है कि व्यायाम करने से हमें बेहतर महसूस होता है।","es":"Las investigaciones muestran que hacer ejercicio nos hace sentir mejor.","vi":"Nghiên cứu cho thấy tập thể dục khiến chúng ta cảm thấy tốt hơn.","ne":"अनुसन्धानले व्यायाम गर्दा हामीलाई राम्रो महसुस हुने देखाउँछ।","fil":"Ipinapakita ng pananaliksik na nakapagpapabuti ng ating pakiramdam ang pag-eehersisyo."},{"n":134,"en":"Before you choose your university courses, you should consider your future career.","ko":"대학 과정을 선택하기 전에 미래의 진로를 고려해야 한다.","meta":["초빈출","보통"],"ceb":"Sa dili pa mopili sa mga kurso sa unibersidad, hunahunaa ang imong umaabot nga karera.","ja":"大学の講座を選ぶ前に将来の職業を考えるべきである。","zh":"在选择大学课程之前，你应该考虑未来的职业。","hi":"विश्वविद्यालय के पाठ्यक्रम चुनने से पहले आपको अपने भविष्य के करियर पर विचार करना चाहिए।","es":"Antes de elegir tus cursos universitarios, debes considerar tu futura carrera profesional.","vi":"Trước khi chọn các khóa học đại học, bạn nên cân nhắc nghề nghiệp tương lai của mình.","ne":"विश्वविद्यालयका पाठ्यक्रम छनोट गर्नुअघि तपाईंले आफ्नो भावी करियरबारे विचार गर्नुपर्छ।","fil":"Bago piliin ang iyong mga kurso sa unibersidad, dapat mong isaalang-alang ang iyong magiging karera."},{"n":135,"en":"Graduates from this course typically pursue careers in financial sector.","ko":"이 과정의 졸업생들은 대개 금융 분야에서 경력을 쌓는다.","meta":["초빈출","핵심예측","보통"],"ceb":"Ang mga migraduwar niini nga kurso kasagarang mangitag karera sa sektor sa pinansiya.","ja":"この講座の卒業生は通常、金融部門でのキャリアを目指す。","zh":"这门课程的毕业生通常在金融领域发展职业。","hi":"इस पाठ्यक्रम के स्नातक आमतौर पर वित्तीय क्षेत्र में करियर बनाते हैं।","es":"Los graduados de este curso suelen desarrollar su carrera en el sector financiero.","vi":"Sinh viên tốt nghiệp khóa học này thường theo đuổi sự nghiệp trong lĩnh vực tài chính.","ne":"यस पाठ्यक्रमबाट स्नातक भएका विद्यार्थीहरू सामान्यतया वित्तीय क्षेत्रमा करियर बनाउँछन्।","fil":"Karaniwang nagpapatuloy sa karera sa sektor ng pananalapi ang mga nagtapos sa kursong ito."},{"n":136,"en":"Tutors should set clear goals at the start of the class.","ko":"지도 교사는 수업 시작 시 명확한 목표를 설정해야 한다.","meta":["초빈출","핵심예측","보통"],"ceb":"Ang mga tutor kinahanglan magtakda og klarong mga tumong sa pagsugod sa klase.","ja":"指導教員は授業の初めに明確な目標を設定すべきである。","zh":"导师应在课程开始时设定明确目标。","hi":"शिक्षकों को कक्षा की शुरुआत में स्पष्ट लक्ष्य निर्धारित करने चाहिए।","es":"Los tutores deben establecer objetivos claros al comienzo de la clase.","vi":"Gia sư nên đặt ra mục tiêu rõ ràng vào đầu buổi học.","ne":"शिक्षकहरूले कक्षाको सुरुमा स्पष्ट लक्ष्यहरू निर्धारण गर्नुपर्छ।","fil":"Dapat magtakda ang mga tutor ng malinaw na layunin sa simula ng klase."},{"n":137,"en":"She began by giving an outline of the previous lecture.","ko":"그녀는 이전 강의의 개요를 설명하는 것으로 시작했다.","meta":["초빈출","핵심예측","쉬움"],"ceb":"Nagsugod siya pinaagi sa paghatag og kinatibuk-ang hulagway sa miaging lektyur.","ja":"彼女は前回の講義の概要を説明することから始めた。","zh":"她首先概述了上一场讲座的内容。","hi":"उन्होंने पिछले व्याख्यान की रूपरेखा बताकर शुरुआत की।","es":"Ella comenzó dando un resumen de la clase anterior.","vi":"Cô ấy bắt đầu bằng việc trình bày khái quát bài giảng trước.","ne":"उनले अघिल्लो व्याख्यानको रूपरेखा दिएर सुरु गरिन्।","fil":"Nagsimula siya sa pagbibigay ng balangkas ng nakaraang lektura."},{"n":138,"en":"Strangely, people are simultaneously impressed by and skeptical about statistics.","ko":"이상하게도 사람들은 통계에 감탄하는 동시에 회의적인 태도를 보인다.","meta":["초빈출","핵심예측","어려움"],"ceb":"Katingad-an nga ang mga tawo nakadayeg ug nagduhaduha sa estadistika sa samang higayon.","ja":"奇妙なことに、人々は統計に感心すると同時に懐疑的でもある。","zh":"奇怪的是，人们既对统计数据印象深刻，又持怀疑态度。","hi":"अजीब बात है कि लोग आँकड़ों से प्रभावित भी होते हैं और उन पर संदेह भी करते हैं।","es":"Curiosamente, las estadísticas impresionan a las personas y al mismo tiempo les generan escepticismo.","vi":"Thật kỳ lạ, mọi người vừa ấn tượng vừa hoài nghi về số liệu thống kê.","ne":"अचम्मको कुरा, मानिसहरू तथ्याङ्कबाट प्रभावित पनि हुन्छन् र त्यसमाथि शङ्का पनि गर्छन्।","fil":"Nakakapagtaka na ang mga tao ay sabay na humahanga at nag-aalinlangan sa estadistika."},{"n":139,"en":"The timetable for the next term will be available next week.","ko":"다음 학기의 시간표는 다음 주에 공개될 예정이다.","meta":["초빈출","쉬움"],"ceb":"Ang iskedyul alang sa sunod nga termino mahimong makuha sunod semana.","ja":"次学期の時間割は来週公開される。","zh":"下学期的课程表将在下周公布。","hi":"अगले सत्र की समयसारणी अगले सप्ताह उपलब्ध होगी।","es":"El horario del próximo período lectivo estará disponible la semana que viene.","vi":"Thời khóa biểu của học kỳ tới sẽ có vào tuần sau.","ne":"अर्को शैक्षिक सत्रको समयतालिका अर्को हप्ता उपलब्ध हुनेछ।","fil":"Magiging available ang iskedyul para sa susunod na termino sa susunod na linggo."},{"n":140,"en":"You must answer security questions when you reset your password.","ko":"비밀번호를 재설정할 때 보안 질문에 답해야 한다.","meta":["초빈출","핵심예측","보통"],"ceb":"Kinahanglan tubagon ang mga security question kon i-reset nimo ang password.","ja":"パスワードを再設定する際にはセキュリティの質問に答えなければならない。","zh":"重置密码时必须回答安全问题。","hi":"अपना पासवर्ड रीसेट करते समय आपको सुरक्षा प्रश्नों के उत्तर देने होंगे।","es":"Debes responder las preguntas de seguridad al restablecer tu contraseña.","vi":"Bạn phải trả lời các câu hỏi bảo mật khi đặt lại mật khẩu.","ne":"पासवर्ड रिसेट गर्दा तपाईंले सुरक्षा प्रश्नहरूको उत्तर दिनुपर्छ।","fil":"Kailangan mong sagutin ang mga tanong sa seguridad kapag nire-reset mo ang iyong password."},{"n":141,"en":"Currently the growth of the economy is unpredictable.","ko":"현재 경제 성장은 예측하기 어렵다.","meta":["초빈출","핵심예측","보통"],"ceb":"Sa pagkakaron, dili matag-an ang pagtubo sa ekonomiya.","ja":"現在、経済成長は予測できない。","zh":"目前经济增长难以预测。","hi":"वर्तमान में अर्थव्यवस्था की वृद्धि का अनुमान लगाना कठिन है।","es":"Actualmente, el crecimiento de la economía es impredecible.","vi":"Hiện tại, tăng trưởng kinh tế rất khó dự đoán.","ne":"हाल अर्थतन्त्रको वृद्धि अनुमान गर्न कठिन छ।","fil":"Sa kasalukuyan, hindi mahuhulaan ang paglago ng ekonomiya."},{"n":142,"en":"The course includes a combination of pure and applied mathematics.","ko":"이 과정에는 순수 수학과 응용 수학이 함께 포함된다.","meta":["초빈출","핵심예측","어려움"],"ceb":"Ang kurso naglakip sa kombinasyon sa pure ug applied mathematics.","ja":"この講座は純粋数学と応用数学を組み合わせた内容を含む。","zh":"这门课程结合了纯数学和应用数学。","hi":"पाठ्यक्रम में शुद्ध और अनुप्रयुक्त गणित का संयोजन शामिल है।","es":"El curso combina matemáticas puras y aplicadas.","vi":"Khóa học kết hợp toán học thuần túy và toán học ứng dụng.","ne":"पाठ्यक्रममा शुद्ध र प्रयोगात्मक गणितको संयोजन समावेश छ।","fil":"Kasama sa kurso ang kombinasyon ng purong matematika at aplikadong matematika."},{"n":143,"en":"Calculators allow us to add numbers without making mistakes.","ko":"계산기를 사용하면 실수 없이 숫자를 더할 수 있다.","meta":["초빈출","핵심예측","보통"],"ceb":"Ang calculator nagtugot kanato sa pagdugang og mga numero nga dili masayop.","ja":"電卓を使えば間違えずに数字を足すことができる。","zh":"计算器让我们能够准确地进行数字加法。","hi":"कैलकुलेटर हमें बिना गलती किए संख्याएँ जोड़ने देते हैं।","es":"Las calculadoras nos permiten sumar números sin cometer errores.","vi":"Máy tính cầm tay cho phép chúng ta cộng các con số mà không mắc lỗi.","ne":"क्याल्कुलेटरले हामीलाई गल्ती नगरी सङ्ख्याहरू जोड्न दिन्छ।","fil":"Nagbibigay-daan ang mga calculator na makapagdagdag tayo ng mga numero nang hindi nagkakamali."},{"n":144,"en":"The stock market crash had repercussions throughout the world.","ko":"주식 시장의 붕괴는 전 세계에 파장을 일으켰다.","meta":["초빈출","핵심예측","어려움"],"ceb":"Ang pagkahugno sa stock market adunay mga epekto sa tibuok kalibotan.","ja":"株式市場の暴落は世界中に影響を及ぼした。","zh":"股市崩盘在世界各地产生了影响。","hi":"शेयर बाजार की गिरावट का असर पूरी दुनिया पर पड़ा।","es":"El desplome de la bolsa tuvo repercusiones en todo el mundo.","vi":"Sự sụp đổ của thị trường chứng khoán gây ảnh hưởng trên toàn thế giới.","ne":"सेयर बजारको पतनले विश्वभर प्रभाव पार्‍यो।","fil":"Nagkaroon ng mga epekto sa buong mundo ang pagbagsak ng stock market."},{"n":145,"en":"Population has a sharp rise in the recent twenty years.","ko":"최근 20년간 인구가 급격히 증가했다.","meta":["초빈출","핵심예측","보통"],"ceb":"Ang populasyon kusog nga misaka sa miaging baynte ka tuig.","ja":"人口は最近の20年間で急増している。","zh":"近二十年来人口急剧增长。","hi":"पिछले बीस वर्षों में जनसंख्या में तीव्र वृद्धि हुई है।","es":"La población ha aumentado considerablemente en los últimos veinte años.","vi":"Dân số đã tăng mạnh trong hai mươi năm gần đây.","ne":"पछिल्ला बीस वर्षमा जनसङ्ख्या तीव्र रूपमा बढेको छ।","fil":"Mabilis na tumaas ang populasyon sa nakalipas na dalawampung taon."},{"n":146,"en":"The museum is closed on the third Monday of every month.","ko":"박물관은 매월 세 번째 월요일에 문을 닫는다.","meta":["초빈출","쉬움"],"ceb":"Sirado ang museyo sa ikatulong Lunes sa matag bulan.","ja":"博物館は毎月第3月曜日に休館する。","zh":"博物馆每月第三个星期一闭馆。","hi":"संग्रहालय प्रत्येक महीने के तीसरे सोमवार को बंद रहता है।","es":"El museo cierra el tercer lunes de cada mes.","vi":"Bảo tàng đóng cửa vào thứ Hai thứ ba của mỗi tháng.","ne":"सङ्ग्रहालय हरेक महिनाको तेस्रो सोमबार बन्द रहन्छ।","fil":"Sarado ang museo tuwing ikatlong Lunes ng bawat buwan."},{"n":147,"en":"You must be able to work in a team.","ko":"팀에서 함께 일할 수 있어야 한다.","meta":["초빈출","핵심예측","쉬움"],"ceb":"Kinahanglan makahimo ka sa pagtrabaho isip kabahin sa usa ka team.","ja":"チームで働ける必要がある。","zh":"你必须具备团队合作能力。","hi":"आपमें टीम में काम करने की क्षमता होनी चाहिए।","es":"Debes ser capaz de trabajar en equipo.","vi":"Bạn phải có khả năng làm việc theo nhóm.","ne":"तपाईं समूहमा काम गर्न सक्षम हुनुपर्छ।","fil":"Kailangan mong marunong makipagtulungan sa isang pangkat."},{"n":148,"en":"Some people believe that education should be free to everyone.","ko":"일부 사람들은 교육이 모든 사람에게 무료여야 한다고 믿는다.","meta":["초빈출","핵심예측","보통"],"ceb":"Ang ubang tawo nagtuo nga ang edukasyon kinahanglan libre alang sa tanan.","ja":"教育はすべての人に無料であるべきだと考える人もいる。","zh":"有些人认为教育应该对所有人免费。","hi":"कुछ लोगों का मानना है कि शिक्षा सभी के लिए निःशुल्क होनी चाहिए।","es":"Algunas personas creen que la educación debería ser gratuita para todos.","vi":"Một số người tin rằng giáo dục nên miễn phí cho mọi người.","ne":"केही मानिस शिक्षा सबैका लागि निःशुल्क हुनुपर्छ भन्ने विश्वास गर्छन्।","fil":"Naniniwala ang ilang tao na dapat libre ang edukasyon para sa lahat."},{"n":149,"en":"You can use your laptops in the lecture.","ko":"강의 중에 노트북을 사용할 수 있다.","meta":["초빈출","핵심예측","쉬움"],"ceb":"Mahimo nimong gamiton ang imong laptop sa lektyur.","ja":"講義中にノートパソコンを使用できる。","zh":"你可以在讲座中使用笔记本电脑。","hi":"आप व्याख्यान में अपने लैपटॉप का उपयोग कर सकते हैं।","es":"Puedes usar tu computadora portátil durante la clase.","vi":"Bạn có thể sử dụng máy tính xách tay trong buổi giảng.","ne":"तपाईं व्याख्यानमा आफ्नो ल्यापटप प्रयोग गर्न सक्नुहुन्छ।","fil":"Maaari mong gamitin ang iyong laptop sa lektura."},{"n":150,"en":"Computers used to be larger than they are now.","ko":"예전의 컴퓨터는 지금보다 더 컸다.","meta":["초빈출","쉬움"],"ceb":"Ang mga computer kaniadto mas dagko kaysa karon.","ja":"コンピューターは以前、現在より大きかった。","zh":"过去的电脑比现在的更大。","hi":"पहले कंप्यूटर आज की तुलना में बड़े हुआ करते थे।","es":"Antes las computadoras eran más grandes que ahora.","vi":"Máy tính trước đây lớn hơn bây giờ.","ne":"पहिलेका कम्प्युटर अहिलेका भन्दा ठूला हुन्थे।","fil":"Mas malalaki noon ang mga computer kaysa ngayon."},{"n":151,"en":"Our faculty includes five libraries across the university.","ko":"우리 학부에는 대학 곳곳에 다섯 개의 도서관이 있다.","meta":["초빈출","핵심예측","쉬움"],"ceb":"Ang among faculty naglakip og lima ka librarya sa tibuok unibersidad.","ja":"私たちの学部には大学全体にわたる五つの図書館が含まれている。","zh":"我们院系包括大学各处的五个图书馆。","hi":"हमारे संकाय में विश्वविद्यालय भर में स्थित पाँच पुस्तकालय शामिल हैं।","es":"Nuestra facultad incluye cinco bibliotecas distribuidas por la universidad.","vi":"Khoa của chúng tôi bao gồm năm thư viện nằm rải rác trong trường đại học.","ne":"हाम्रो संकायमा विश्वविद्यालयभर रहेका पाँचवटा पुस्तकालय समावेश छन्।","fil":"Kasama sa aming fakultad ang limang aklatan sa iba't ibang bahagi ng unibersidad."},{"n":152,"en":"The department is doing some crucial work on climate change.","ko":"해당 부서는 기후 변화에 관한 중요한 업무를 수행하고 있다.","meta":["초빈출","보통"],"ceb":"Ang departamento naghimo og importanteng trabaho bahin sa kausaban sa klima.","ja":"その学科は気候変動に関する重要な研究を行っている。","zh":"该部门正在进行一些有关气候变化的重要工作。","hi":"विभाग जलवायु परिवर्तन पर कुछ महत्वपूर्ण काम कर रहा है।","es":"El departamento está realizando una labor crucial sobre el cambio climático.","vi":"Khoa đang thực hiện một số công việc quan trọng về biến đổi khí hậu.","ne":"विभागले जलवायु परिवर्तनसम्बन्धी केही महत्त्वपूर्ण काम गरिरहेको छ।","fil":"Gumagawa ang departamento ng mahalagang gawain tungkol sa pagbabago ng klima."},{"n":153,"en":"The library will be closed for staff training tomorrow morning.","ko":"도서관은 직원 교육으로 인해 내일 오전에 문을 닫을 것이다.","meta":["초빈출","보통"],"ceb":"Sirado ang librarya ugma sa buntag alang sa pagbansay sa mga kawani.","ja":"図書館は明日の午前中、職員研修のため閉館する。","zh":"图书馆明天上午因员工培训而关闭。","hi":"कर्मचारियों के प्रशिक्षण के लिए पुस्तकालय कल सुबह बंद रहेगा।","es":"La biblioteca estará cerrada mañana por la mañana debido a la formación del personal.","vi":"Thư viện sẽ đóng cửa vào sáng mai để đào tạo nhân viên.","ne":"कर्मचारी तालिमका लागि पुस्तकालय भोलि बिहान बन्द रहनेछ।","fil":"Isasara ang aklatan bukas ng umaga para sa pagsasanay ng mga kawani."},{"n":154,"en":"Too much information may have been avoided by the group research design.","ko":"그룹 연구 설계를 통해 과도한 정보가 배제되었을 수도 있다.","meta":["초빈출","어려움"],"ceb":"Ang sobra nga impormasyon tingali nalikayan pinaagi sa disenyo sa panukiduki sa grupo.","ja":"グループ研究の設計によって過剰な情報が避けられた可能性がある。","zh":"小组研究设计可能避免了信息过多的问题。","hi":"समूह शोध की रूपरेखा से संभवतः अत्यधिक जानकारी एकत्र होने से बचा गया।","es":"El diseño de la investigación grupal quizá evitó un exceso de información.","vi":"Thiết kế nghiên cứu nhóm có thể đã giúp tránh tình trạng quá nhiều thông tin.","ne":"समूह अनुसन्धानको डिजाइनले अत्यधिक जानकारी प्राप्त हुनबाट सम्भवतः जोगाएको थियो।","fil":"Maaaring naiwasan ang sobrang impormasyon dahil sa disenyo ng pananaliksik ng pangkat."},{"n":155,"en":"Plants are able to continue growing throughout their lives.","ko":"식물은 평생 동안 계속 자랄 수 있다.","meta":["초빈출","보통"],"ceb":"Ang mga tanom makapadayon sa pagtubo sa tibuok nilang kinabuhi.","ja":"植物は生涯にわたって成長し続けることができる。","zh":"植物能够在一生中持续生长。","hi":"पौधे अपने पूरे जीवनकाल में बढ़ते रह सकते हैं।","es":"Las plantas pueden seguir creciendo durante toda su vida.","vi":"Thực vật có thể tiếp tục phát triển trong suốt cuộc đời của chúng.","ne":"वनस्पतिहरू आफ्नो जीवनभर बढिरहन सक्छन्।","fil":"Maaaring patuloy na lumaki ang mga halaman sa buong buhay nila."},{"n":156,"en":"You need to put those books on the table over there.","ko":"저 책들을 저쪽에 있는 탁자 위에 놓아야 한다.","meta":["초빈출","핵심예측","쉬움"],"ceb":"Kinahanglan ibutang nimo kadtong mga libro sa lamesa didto.","ja":"それらの本をあそこの机に置く必要がある。","zh":"你需要把那些书放在那边的桌子上。","hi":"आपको वे किताबें वहाँ रखी मेज पर रखनी हैं।","es":"Debes poner esos libros en aquella mesa.","vi":"Bạn cần đặt những cuốn sách đó lên chiếc bàn đằng kia.","ne":"तपाईंले ती किताबहरू त्यहाँको टेबलमा राख्नुपर्छ।","fil":"Kailangan mong ilagay ang mga librong iyon sa mesa roon."},{"n":157,"en":"Universities need to secure research funds for projects.","ko":"대학은 프로젝트를 위한 연구 자금을 확보해야 한다.","meta":["초빈출","핵심예측","보통"],"ceb":"Ang mga unibersidad kinahanglan makakuha og pondo sa panukiduki alang sa mga proyekto.","ja":"大学はプロジェクトの研究資金を確保する必要がある。","zh":"大学需要为项目争取研究资金。","hi":"विश्वविद्यालयों को परियोजनाओं के लिए शोध निधि सुनिश्चित करनी होती है।","es":"Las universidades necesitan conseguir fondos de investigación para sus proyectos.","vi":"Các trường đại học cần đảm bảo nguồn tài trợ nghiên cứu cho các dự án.","ne":"विश्वविद्यालयहरूले परियोजनाका लागि अनुसन्धान कोष सुनिश्चित गर्नुपर्छ।","fil":"Kailangang makakuha ang mga unibersidad ng pondo para sa mga proyektong pananaliksik."},{"n":158,"en":"The office hours will change from next term.","ko":"사무실 운영 시간은 다음 학기부터 변경될 것이다.","meta":["초빈출","핵심예측","쉬움"],"ceb":"Ang oras sa opisina mausab sugod sa sunod nga termino.","ja":"事務室の受付時間は次学期から変わる。","zh":"办公时间将从下学期开始调整。","hi":"अगले सत्र से कार्यालय का समय बदल जाएगा।","es":"El horario de atención cambiará a partir del próximo período lectivo.","vi":"Giờ làm việc của văn phòng sẽ thay đổi từ học kỳ tới.","ne":"कार्यालय खुल्ने समय अर्को शैक्षिक सत्रदेखि बदलिनेछ।","fil":"Magbabago ang oras ng opisina simula sa susunod na termino."},{"n":159,"en":"Football is played throughout all years at the university.","ko":"이 대학에서는 일 년 내내 축구를 한다.","meta":["초빈출","핵심예측","보통"],"ceb":"Ang football ginadula sa tanang year level sa unibersidad.","ja":"大学ではすべての学年でサッカーが行われている。","zh":"大学各年级都开展足球运动。","hi":"विश्वविद्यालय में सभी वर्ष के विद्यार्थी फुटबॉल खेलते हैं।","es":"Se juega al fútbol en todos los cursos de la universidad.","vi":"Bóng đá được chơi ở tất cả các năm học tại trường đại học.","ne":"विश्वविद्यालयका सबै वर्षका विद्यार्थीहरूले फुटबल खेल्छन्।","fil":"Naglalaro ng football ang mga nasa lahat ng taon sa unibersidad."},{"n":160,"en":"We are looking for new ways to engage learners.","ko":"우리는 학습자의 참여를 유도할 새로운 방법을 찾고 있다.","meta":["초빈출","핵심예측","보통"],"ceb":"Nangita kami og bag-ong mga paagi aron maengganyo ang mga tigkat-on.","ja":"私たちは学習者の関心を引く新しい方法を探している。","zh":"我们正在寻找吸引学习者参与的新方法。","hi":"हम शिक्षार्थियों को सक्रिय रूप से जोड़ने के नए तरीके खोज रहे हैं।","es":"Buscamos nuevas formas de involucrar a los estudiantes.","vi":"Chúng tôi đang tìm kiếm những cách mới để thu hút người học tham gia.","ne":"हामी सिक्नेहरूलाई सक्रिय रूपमा सहभागी गराउने नयाँ तरिकाहरू खोजिरहेका छौँ।","fil":"Naghahanap kami ng mga bagong paraan upang mahikayat ang mga mag-aaral na makilahok."},{"n":161,"en":"There is probably life in the other planets in the universe.","ko":"우주의 다른 행성에도 생명체가 있을 가능성이 있다.","meta":["초빈출","핵심예측","어려움"],"ceb":"Posible nga adunay kinabuhi sa ubang planeta sa uniberso.","ja":"宇宙の他の惑星にもおそらく生命が存在する。","zh":"宇宙中的其他行星上可能存在生命。","hi":"ब्रह्मांड के अन्य ग्रहों पर संभवतः जीवन है।","es":"Probablemente haya vida en otros planetas del universo.","vi":"Có lẽ sự sống tồn tại trên những hành tinh khác trong vũ trụ.","ne":"ब्रह्माण्डका अन्य ग्रहहरूमा सम्भवतः जीवन छ।","fil":"Malamang na may buhay sa ibang mga planeta sa uniberso."},{"n":162,"en":"Without doubt, this theory has a number of limitations.","ko":"의심할 여지 없이 이 이론에는 여러 가지 한계가 있다.","meta":["초빈출","핵심예측","보통"],"ceb":"Walay duha-duha nga kini nga teoriya adunay daghang limitasyon.","ja":"間違いなく、この理論にはいくつかの限界がある。","zh":"毫无疑问，这一理论存在若干局限性。","hi":"निःसंदेह, इस सिद्धांत की कई सीमाएँ हैं।","es":"Sin duda, esta teoría tiene varias limitaciones.","vi":"Không nghi ngờ gì, lý thuyết này có một số hạn chế.","ne":"निःसन्देह, यस सिद्धान्तका केही सीमाहरू छन्।","fil":"Walang duda na may ilang limitasyon ang teoryang ito."},{"n":163,"en":"The teacher training course includes observing the classes.","ko":"교사 양성 과정에는 수업 참관이 포함된다.","meta":["초빈출","핵심예측","쉬움"],"ceb":"Ang kurso sa pagbansay sa magtutudlo naglakip sa pag-obserbar sa mga klase.","ja":"教員養成講座には授業の見学が含まれる。","zh":"教师培训课程包括课堂观察。","hi":"शिक्षक प्रशिक्षण पाठ्यक्रम में कक्षाओं का अवलोकन शामिल है।","es":"El curso de formación docente incluye la observación de clases.","vi":"Khóa đào tạo giáo viên bao gồm việc quan sát các lớp học.","ne":"शिक्षक तालिम पाठ्यक्रममा कक्षाहरूको अवलोकन समावेश छ।","fil":"Kasama sa kurso sa pagsasanay ng guro ang pagmamasid sa mga klase."},{"n":164,"en":"Chemical reactions occur when substances combine or change.","ko":"물질이 결합하거나 변화할 때 화학 반응이 일어난다.","meta":["초빈출","핵심예측","어려움"],"ceb":"Mahitabo ang kemikal nga reaksiyon kon ang mga substansiya maghiusa o mausab.","ja":"物質が結合したり変化したりすると化学反応が起こる。","zh":"当物质结合或发生变化时，就会产生化学反应。","hi":"रासायनिक प्रतिक्रियाएँ तब होती हैं जब पदार्थ मिलते हैं या बदलते हैं।","es":"Las reacciones químicas ocurren cuando las sustancias se combinan o cambian.","vi":"Phản ứng hóa học xảy ra khi các chất kết hợp hoặc biến đổi.","ne":"पदार्थहरू मिसिँदा वा परिवर्तन हुँदा रासायनिक प्रतिक्रिया हुन्छ।","fil":"Nagaganap ang mga reaksiyong kemikal kapag nagsasama o nagbabago ang mga sangkap."},{"n":165,"en":"All experimental procedures are outlined in the laboratory manual.","ko":"모든 실험 절차는 실험실 매뉴얼에 개략적으로 설명되어 있다.","meta":["초빈출","어려움"],"ceb":"Ang tanang pamaagi sa eksperimento gilatid sa laboratory manual.","ja":"すべての実験手順は実験室のマニュアルに記載されている。","zh":"实验室手册概述了所有实验步骤。","hi":"प्रयोगशाला की पुस्तिका में सभी प्रयोगात्मक प्रक्रियाओं की रूपरेखा दी गई है।","es":"Todos los procedimientos experimentales se describen en el manual de laboratorio.","vi":"Tất cả quy trình thí nghiệm được trình bày trong sổ tay phòng thí nghiệm.","ne":"प्रयोगशालाको निर्देशिकामा सबै प्रयोगात्मक प्रक्रियाको रूपरेखा दिइएको छ।","fil":"Nakabalangkas sa manwal ng laboratoryo ang lahat ng pamamaraan ng eksperimento."},{"n":166,"en":"Please return the textbooks to the correct bookshelves in the library.","ko":"교과서를 도서관의 올바른 책장에 반납해 주세요.","meta":["초빈출","핵심예측","보통"],"ceb":"Palihog ibalik ang mga textbook sa hustong estante sa librarya.","ja":"教科書は図書館の正しい本棚に戻してください。","zh":"请将课本归还到图书馆正确的书架上。","hi":"कृपया पाठ्यपुस्तकों को पुस्तकालय की सही अलमारियों में वापस रखें।","es":"Devuelve los libros de texto a las estanterías correctas de la biblioteca.","vi":"Vui lòng trả sách giáo khoa về đúng kệ trong thư viện.","ne":"कृपया पाठ्यपुस्तकहरू पुस्तकालयका सही दराजहरूमा फिर्ता राख्नुहोस्।","fil":"Pakibalik ang mga aklat-aralin sa tamang mga estante sa aklatan."},{"n":167,"en":"The professor will have a lecture in the class.","ko":"교수님은 수업에서 강의를 할 예정이다.","meta":["초빈출","쉬움"],"ceb":"Ang propesor mohatag og lektyur sa klase.","ja":"教授は授業で講義を行う予定である。","zh":"教授将在课堂上举行讲座。","hi":"प्रोफेसर कक्षा में व्याख्यान देंगे।","es":"El profesor dará una clase magistral en el aula.","vi":"Giáo sư sẽ có một bài giảng trên lớp.","ne":"प्राध्यापकले कक्षामा व्याख्यान दिनेछन्।","fil":"Magbibigay ng lektura ang propesor sa klase."},{"n":168,"en":"Her design incorporates the best aspects of vernacular architecture.","ko":"그녀의 설계에는 지역 전통 건축의 가장 뛰어난 요소들이 반영되어 있다.","meta":["초빈출","어려움"],"ceb":"Ang iyang disenyo naglakip sa labing maayong bahin sa lokal nga tradisyonal nga arkitektura.","ja":"彼女の設計には地域固有の建築の優れた側面が取り入れられている。","zh":"她的设计融入了乡土建筑的最佳特点。","hi":"उनके डिजाइन में स्थानीय पारंपरिक वास्तुकला के सर्वोत्तम पहलू शामिल हैं।","es":"Su diseño incorpora los mejores aspectos de la arquitectura vernácula.","vi":"Thiết kế của cô kết hợp những khía cạnh tốt nhất của kiến trúc bản địa.","ne":"उनको डिजाइनमा स्थानीय परम्परागत वास्तुकलाका उत्कृष्ट पक्षहरू समावेश छन्।","fil":"Isinasama ng kanyang disenyo ang pinakamagagandang katangian ng katutubong arkitektura."},{"n":169,"en":"Nursing is defined as medical practice and clinical work.","ko":"간호는 의료 실무와 임상 업무로 정의된다.","meta":["초빈출","어려움"],"ceb":"Ang nursing gihubit isip medikal nga praktis ug klinikal nga trabaho.","ja":"看護は医療実践と臨床業務と定義される。","zh":"护理被定义为医疗实践和临床工作。","hi":"नर्सिंग को चिकित्सा अभ्यास और नैदानिक कार्य के रूप में परिभाषित किया जाता है।","es":"La enfermería se define como práctica médica y trabajo clínico.","vi":"Điều dưỡng được định nghĩa là thực hành y khoa và công việc lâm sàng.","ne":"नर्सिङलाई चिकित्सा अभ्यास र क्लिनिकल कामका रूपमा परिभाषित गरिन्छ।","fil":"Ang nursing ay tinutukoy bilang medikal na pagsasanay at klinikal na gawain."},{"n":170,"en":"You should be part of the team.","ko":"당신은 팀의 일원이 되어야 한다.","meta":["초빈출","핵심예측","쉬움"],"ceb":"Kinahanglan mahimong kabahin ka sa team.","ja":"あなたはチームの一員になるべきである。","zh":"你应该成为团队的一员。","hi":"आपको टीम का हिस्सा होना चाहिए।","es":"Deberías formar parte del equipo.","vi":"Bạn nên là một phần của nhóm.","ne":"तपाईं टोलीको सदस्य हुनुपर्छ।","fil":"Dapat kang maging bahagi ng pangkat."},{"n":171,"en":"The university requires all new students to attend an orientation session before classes begin.","ko":"대학은 모든 신입생이 수업 시작 전에 오리엔테이션에 참석하도록 요구한다.","meta":["초빈출","핵심예측","어려움"],"ceb":"Ang unibersidad nagkinahanglan nga ang tanang bag-ong estudyante motambong sa orientation sa dili pa magsugod ang klase.","ja":"大学はすべての新入生に授業開始前のオリエンテーションへの参加を求めている。","zh":"大学要求所有新生在开课前参加入学介绍会。","hi":"विश्वविद्यालय में सभी नए विद्यार्थियों को कक्षाएँ शुरू होने से पहले परिचय सत्र में भाग लेना आवश्यक है।","es":"La universidad exige que todos los estudiantes nuevos asistan a una sesión de orientación antes de comenzar las clases.","vi":"Trường đại học yêu cầu tất cả sinh viên mới tham dự buổi định hướng trước khi bắt đầu học.","ne":"विश्वविद्यालयले सबै नयाँ विद्यार्थीलाई कक्षा सुरु हुनुअघि अभिमुखीकरण सत्रमा सहभागी हुन अनिवार्य गरेको छ।","fil":"Inaatasan ng unibersidad ang lahat ng bagong estudyante na dumalo sa oryentasyon bago magsimula ang klase."},{"n":172,"en":"Affordable housing is an important issue for all members of society.","ko":"저렴한 주택은 사회의 모든 구성원에게 중요한 문제이다.","meta":["빈도하락","보통"],"ceb":"Ang barato nga balay usa ka importanteng isyu alang sa tanang miyembro sa katilingban.","ja":"手頃な価格の住宅は社会のすべての人々にとって重要な問題である。","zh":"经济适用住房是所有社会成员都关心的重要问题。","hi":"किफायती आवास समाज के सभी सदस्यों के लिए एक महत्वपूर्ण मुद्दा है।","es":"La vivienda asequible es un asunto importante para todos los miembros de la sociedad.","vi":"Nhà ở giá phải chăng là vấn đề quan trọng đối với mọi thành viên trong xã hội.","ne":"किफायती आवास समाजका सबै सदस्यका लागि महत्त्वपूर्ण मुद्दा हो।","fil":"Ang abot-kayang pabahay ay mahalagang usapin para sa lahat ng miyembro ng lipunan."},{"n":173,"en":"Americans have typically defined the process of plant growth in quantitative terms.","ko":"미국인들은 일반적으로 식물의 성장 과정을 정량적 용어로 정의해 왔다.","meta":["빈도하락","어려움"],"ceb":"Ang mga Amerikano kasagarang naghubit sa proseso sa pagtubo sa tanom pinaagi sa masukod nga mga termino.","ja":"アメリカ人は一般に植物の成長過程を定量的に定義してきた。","zh":"美国人通常以定量方式描述植物生长过程。","hi":"अमेरिकी आमतौर पर पौधों की वृद्धि की प्रक्रिया को मात्रात्मक शब्दों में परिभाषित करते आए हैं।","es":"Los estadounidenses suelen definir el proceso de crecimiento vegetal en términos cuantitativos.","vi":"Người Mỹ thường định nghĩa quá trình sinh trưởng của thực vật bằng các thuật ngữ định lượng.","ne":"अमेरिकीहरूले सामान्यतया वनस्पति वृद्धिको प्रक्रियालाई परिमाणात्मक शब्दमा परिभाषित गरेका छन्।","fil":"Karaniwang inilalarawan ng mga Amerikano ang proseso ng paglaki ng halaman sa mga terminong kuwantitatibo."},{"n":174,"en":"An introduction is an essential element of presentation.","ko":"서론은 발표의 필수 요소이다.","meta":["빈도하락","쉬움"],"ceb":"Ang introduksiyon usa ka importanteng elemento sa presentasyon.","ja":"導入部はプレゼンテーションに不可欠な要素である。","zh":"引言是演示的重要组成部分。","hi":"परिचय किसी प्रस्तुति का अनिवार्य तत्व है।","es":"Una introducción es un elemento esencial de una presentación.","vi":"Phần giới thiệu là yếu tố thiết yếu của bài thuyết trình.","ne":"परिचय प्रस्तुतिको अनिवार्य तत्त्व हो।","fil":"Ang introduksiyon ay isang mahalagang elemento ng presentasyon."},{"n":175,"en":"Despite their differences, all forms of life share certain characteristics.","ko":"차이점에도 불구하고 모든 생명체는 특정한 공통 특성을 지닌다.","meta":["빈도하락","보통"],"ceb":"Bisan sa ilang mga kalainan, ang tanang matang sa kinabuhi adunay pipila ka komon nga kinaiya.","ja":"違いはあっても、あらゆる生命形態には共通する特徴がある。","zh":"尽管存在差异，所有生命形式都具有某些共同特征。","hi":"अपने अंतरों के बावजूद जीवन के सभी रूपों में कुछ समान विशेषताएँ होती हैं।","es":"A pesar de sus diferencias, todas las formas de vida comparten ciertas características.","vi":"Dù khác biệt, mọi dạng sống đều có chung một số đặc điểm.","ne":"भिन्नता हुँदाहुँदै पनि जीवनका सबै स्वरूपमा केही समान विशेषताहरू हुन्छन्।","fil":"Sa kabila ng kanilang pagkakaiba, may ilang katangiang magkakatulad ang lahat ng anyo ng buhay."},{"n":176,"en":"Human beings compete with other living things for resources and space.","ko":"인간은 자원과 공간을 두고 다른 생물들과 경쟁한다.","meta":["빈도하락","보통"],"ceb":"Ang mga tawo makigkompetensiya sa ubang buhing butang alang sa mga kahinguhaan ug lugar.","ja":"人間は資源と空間をめぐって他の生物と競争する。","zh":"人类与其他生物争夺资源和空间。","hi":"मनुष्य संसाधनों और स्थान के लिए अन्य जीवित प्राणियों से प्रतिस्पर्धा करते हैं।","es":"Los seres humanos compiten con otros seres vivos por los recursos y el espacio.","vi":"Con người cạnh tranh với các sinh vật khác về tài nguyên và không gian.","ne":"मानिसहरू स्रोत र स्थानका लागि अन्य जीवित प्राणीसँग प्रतिस्पर्धा गर्छन्।","fil":"Nakikipagkompetensiya ang mga tao sa ibang mga buhay na organismo para sa mga yaman at espasyo."},{"n":177,"en":"It may not be possible to solve the problem easily.","ko":"그 문제를 쉽게 해결하는 것은 불가능할 수도 있다.","meta":["빈도하락","쉬움"],"ceb":"Tingali dili posible nga masulbad ang problema sa sayong paagi.","ja":"その問題を簡単に解決することはできないかもしれない。","zh":"这个问题可能无法轻易解决。","hi":"समस्या को आसानी से हल करना संभव नहीं भी हो सकता है।","es":"Puede que no sea posible resolver el problema fácilmente.","vi":"Có thể không dễ dàng giải quyết được vấn đề.","ne":"समस्या सजिलै समाधान गर्न सम्भव नहुन सक्छ।","fil":"Maaaring hindi madaling malutas ang problema."},{"n":178,"en":"Organizational failure is considered from various perspectives in academic literature.","ko":"학술 문헌에서는 조직의 실패를 다양한 관점에서 고찰한다.","meta":["빈도하락","어려움"],"ceb":"Ang kapakyasan sa organisasyon gisusi gikan sa lainlaing panglantaw sa akademikong literatura.","ja":"組織の失敗は学術文献でさまざまな観点から考察されている。","zh":"学术文献从不同角度探讨组织失败。","hi":"शैक्षणिक साहित्य में संगठनात्मक विफलता पर विभिन्न दृष्टिकोणों से विचार किया जाता है।","es":"El fracaso organizacional se analiza desde diversas perspectivas en la literatura académica.","vi":"Sự thất bại của tổ chức được xem xét từ nhiều góc độ trong tài liệu học thuật.","ne":"शैक्षिक साहित्यमा सङ्गठनात्मक असफलतालाई विभिन्न दृष्टिकोणबाट हेरिन्छ।","fil":"Sinusuri ang kabiguan ng organisasyon mula sa iba't ibang pananaw sa akademikong literatura."},{"n":179,"en":"Some people argue that education is not that important.","ko":"일부 사람들은 교육이 그다지 중요하지 않다고 주장한다.","meta":["빈도하락","쉬움"],"ceb":"Ang ubang tawo nag-ingon nga dili kaayo importante ang edukasyon.","ja":"教育はそれほど重要ではないと主張する人もいる。","zh":"有些人认为教育并没有那么重要。","hi":"कुछ लोगों का तर्क है कि शिक्षा इतनी महत्वपूर्ण नहीं है।","es":"Algunas personas sostienen que la educación no es tan importante.","vi":"Một số người cho rằng giáo dục không quan trọng đến thế.","ne":"केही मानिस शिक्षा त्यति महत्त्वपूर्ण छैन भनी तर्क गर्छन्।","fil":"Iginigiit ng ilang tao na hindi ganoon kahalaga ang edukasyon."},{"n":180,"en":"One of the election promises is to decrease income taxes.","ko":"선거 공약 중 하나는 소득세를 인하하는 것이다.","meta":["빈도하락","보통"],"ceb":"Usa sa mga saad sa eleksiyon mao ang pagpaubos sa buhis sa kita.","ja":"選挙公約の一つは所得税を引き下げることである。","zh":"竞选承诺之一是降低所得税。","hi":"चुनावी वादों में से एक आयकर कम करना है।","es":"Una de las promesas electorales es reducir los impuestos sobre la renta.","vi":"Một trong những lời hứa tranh cử là giảm thuế thu nhập.","ne":"चुनावी वाचाहरूमध्ये एउटा आयकर घटाउनु हो।","fil":"Isa sa mga pangako sa halalan ang pagpapababa ng buwis sa kita."},{"n":181,"en":"Make sure you’ve saved all files before turning off the computer.","ko":"컴퓨터를 끄기 전에 모든 파일을 저장했는지 확인하세요.","meta":["빈도하락","보통"],"ceb":"Siguroha nga na-save na nimo ang tanang file sa dili pa palungon ang computer.","ja":"コンピューターの電源を切る前にすべてのファイルを保存したか確認してください。","zh":"关闭电脑之前，请确保已保存所有文件。","hi":"कंप्यूटर बंद करने से पहले सुनिश्चित करें कि आपने सभी फाइलें सहेज ली हैं।","es":"Asegúrate de haber guardado todos los archivos antes de apagar la computadora.","vi":"Hãy chắc chắn đã lưu tất cả các tệp trước khi tắt máy tính.","ne":"कम्प्युटर बन्द गर्नुअघि सबै फाइल सुरक्षित गरेको सुनिश्चित गर्नुहोस्।","fil":"Tiyaking nai-save mo na ang lahat ng file bago patayin ang computer."},{"n":182,"en":"The coffee machine located on the third floor is not working today.","ko":"3층에 있는 커피 머신은 오늘 작동하지 않는다.","meta":["빈도하락","보통"],"ceb":"Ang coffee machine sa ikatulong andana dili mogana karong adlawa.","ja":"3階にあるコーヒーマシンは今日は故障している。","zh":"位于三楼的咖啡机今天无法使用。","hi":"तीसरी मंजिल पर स्थित कॉफी मशीन आज काम नहीं कर रही है।","es":"La máquina de café situada en el tercer piso no funciona hoy.","vi":"Máy pha cà phê ở tầng ba hôm nay không hoạt động.","ne":"तेस्रो तलामा रहेको कफी मेसिन आज चलिरहेको छैन।","fil":"Hindi gumagana ngayong araw ang coffee machine na nasa ikatlong palapag."},{"n":183,"en":"Politicians need to be more proactive when they are addressing the green issues.","ko":"정치인들은 환경 문제를 다룰 때 더욱 적극적이어야 한다.","meta":["빈도하락","보통"],"ceb":"Ang mga politiko kinahanglan mas aktibong molihok sa pagsulbad sa mga isyu sa kinaiyahan.","ja":"政治家は環境問題に取り組む際、より積極的になる必要がある。","zh":"政治家在处理环保问题时需要更加积极主动。","hi":"पर्यावरण संबंधी मुद्दों को संबोधित करते समय राजनेताओं को अधिक सक्रिय पहल करनी चाहिए।","es":"Los políticos deben ser más proactivos al abordar los problemas ambientales.","vi":"Các chính trị gia cần chủ động hơn khi giải quyết các vấn đề môi trường.","ne":"वातावरणीय समस्याहरू सम्बोधन गर्दा राजनीतिज्ञहरू थप सक्रिय हुनुपर्छ।","fil":"Kailangang maging mas maagap ang mga politiko sa pagharap sa mga isyung pangkapaligiran."},{"n":184,"en":"This part of the course is about psychology.","ko":"이 과정의 이 부분은 심리학에 관한 것이다.","meta":["빈도하락","쉬움"],"ceb":"Kini nga bahin sa kurso mahitungod sa psychology.","ja":"講座のこの部分は心理学についてである。","zh":"课程的这一部分是关于心理学的。","hi":"पाठ्यक्रम का यह हिस्सा मनोविज्ञान के बारे में है।","es":"Esta parte del curso trata sobre psicología.","vi":"Phần này của khóa học nói về tâm lý học.","ne":"पाठ्यक्रमको यो भाग मनोविज्ञानसम्बन्धी हो।","fil":"Tungkol sa sikolohiya ang bahaging ito ng kurso."},{"n":185,"en":"Building trust is not something that can be achieved overnight.","ko":"신뢰를 쌓는 것은 하루아침에 이루어질 수 있는 일이 아니다.","meta":["빈도하락","보통"],"ceb":"Ang pagtukod og pagsalig dili makab-ot sa usa lang ka gabii.","ja":"信頼関係の構築は一晩でできるものではない。","zh":"建立信任不是一夜之间就能实现的事情。","hi":"विश्वास कायम करना ऐसा काम नहीं है जो रातोंरात हो जाए।","es":"Generar confianza no es algo que se logre de la noche a la mañana.","vi":"Xây dựng lòng tin không phải là việc có thể đạt được trong một sớm một chiều.","ne":"विश्वास निर्माण गर्नु एकै रातमा हासिल गर्न सकिने काम होइन।","fil":"Ang pagbuo ng tiwala ay hindi isang bagay na makakamit sa magdamag."},{"n":186,"en":"While some people regard it as reforming zeal, others regard it as recklessness.","ko":"어떤 사람들은 그것을 개혁에 대한 열정으로 보는 반면, 다른 사람들은 무모함으로 본다.","meta":["빈도하락","어려움"],"ceb":"Samtang ang uban nagtan-aw niini isip kadasig sa reporma, ang uban nagtan-aw niini isip pagkamapadulom sa peligro nga walay pag-amping.","ja":"それを改革への熱意と見なす人もいれば、無謀さと見なす人もいる。","zh":"有些人认为这是改革热情，另一些人则认为这是鲁莽。","hi":"जहाँ कुछ लोग इसे सुधार का उत्साह मानते हैं, वहीं अन्य इसे लापरवाही मानते हैं।","es":"Mientras algunos lo consideran afán reformista, otros lo consideran imprudencia.","vi":"Trong khi một số người coi đó là nhiệt huyết cải cách, những người khác lại coi đó là sự liều lĩnh.","ne":"केही मानिस यसलाई सुधारको उत्साह मान्छन् भने अरूले यसलाई लापरवाही मान्छन्।","fil":"Habang itinuturing ito ng ilan na sigasig sa reporma, itinuturing naman ito ng iba na kawalang-ingat."},{"n":187,"en":"Gold is a metal that appears naturally and in a pure state.","ko":"금은 자연에서 순수한 상태로 나타나는 금속이다.","meta":["빈도하락","쉬움"],"ceb":"Ang bulawan usa ka metal nga natural nga makita sa putli nga kahimtang.","ja":"金は自然界に純粋な状態で存在する金属である。","zh":"黄金是一种天然存在且可以纯态出现的金属。","hi":"सोना एक धातु है जो प्राकृतिक रूप से शुद्ध अवस्था में पाई जाती है।","es":"El oro es un metal que aparece de forma natural y en estado puro.","vi":"Vàng là một kim loại xuất hiện tự nhiên ở trạng thái tinh khiết.","ne":"सुन प्राकृतिक रूपमा शुद्ध अवस्थामा पाइने धातु हो।","fil":"Ang ginto ay isang metal na likas na matatagpuan sa dalisay na anyo."},{"n":188,"en":"Neuroscience is a compound of completely separate parts.","ko":"신경과학은 완전히 분리된 부분들이 결합된 것이다.","meta":["빈도하락","어려움"],"ceb":"Ang neuroscience usa ka kombinasyon sa hingpit nga bulag nga mga bahin.","ja":"神経科学は完全に別個の部分からなる複合体である。","zh":"神经科学是由完全独立的部分组成的综合体。","hi":"तंत्रिका विज्ञान पूरी तरह अलग-अलग भागों का एक संयोजन है।","es":"La neurociencia es un conjunto de partes completamente separadas.","vi":"Khoa học thần kinh là một tổ hợp gồm những phần hoàn toàn tách biệt.","ne":"स्नायुविज्ञान पूर्ण रूपमा अलग भागहरूको संयोजन हो।","fil":"Ang neuroscience ay isang pinagsamang larangan na binubuo ng ganap na magkakahiwalay na bahagi."},{"n":189,"en":"The investment will be dedicated to improving transport infrastructure.","ko":"투자금은 교통 인프라 개선에 사용될 것이다.","meta":["빈도하락","어려움"],"ceb":"Ang puhunan igahin alang sa pagpauswag sa imprastraktura sa transportasyon.","ja":"その投資は交通インフラの改善に充てられる。","zh":"这笔投资将用于改善交通基础设施。","hi":"निवेश परिवहन अवसंरचना को बेहतर बनाने के लिए समर्पित होगा।","es":"La inversión se destinará a mejorar la infraestructura de transporte.","vi":"Khoản đầu tư sẽ được dành để cải thiện cơ sở hạ tầng giao thông.","ne":"लगानी यातायात पूर्वाधार सुधार गर्न समर्पित हुनेछ।","fil":"Ilalaan ang pamumuhunan sa pagpapabuti ng imprastraktura ng transportasyon."},{"n":190,"en":"New developments in manufacturing play an important role in our lives.","ko":"제조업의 새로운 발전은 우리의 삶에서 중요한 역할을 한다.","meta":["빈도하락","어려움"],"ceb":"Ang bag-ong mga kalamboan sa manufacturing adunay importanteng papel sa atong kinabuhi.","ja":"製造業の新たな発展は私たちの生活で重要な役割を果たす。","zh":"制造业的新发展在我们的生活中发挥着重要作用。","hi":"विनिर्माण में नए विकास हमारे जीवन में महत्वपूर्ण भूमिका निभाते हैं।","es":"Los nuevos avances en la fabricación desempeñan un papel importante en nuestras vidas.","vi":"Những tiến bộ mới trong sản xuất đóng vai trò quan trọng trong cuộc sống của chúng ta.","ne":"उत्पादन क्षेत्रमा भएका नयाँ विकासले हाम्रो जीवनमा महत्त्वपूर्ण भूमिका खेल्छन्।","fil":"May mahalagang papel sa ating buhay ang mga bagong pagsulong sa pagmamanupaktura."},{"n":191,"en":"Practical experience is an essential part of the course.","ko":"실무 경험은 이 과정의 필수적인 부분이다.","meta":["빈도하락","보통"],"ceb":"Ang praktikal nga kasinatian usa ka importanteng bahin sa kurso.","ja":"実務経験はこの講座に不可欠な部分である。","zh":"实践经验是这门课程不可或缺的一部分。","hi":"व्यावहारिक अनुभव पाठ्यक्रम का अनिवार्य हिस्सा है।","es":"La experiencia práctica es una parte esencial del curso.","vi":"Kinh nghiệm thực tế là một phần thiết yếu của khóa học.","ne":"व्यावहारिक अनुभव पाठ्यक्रमको अनिवार्य भाग हो।","fil":"Ang praktikal na karanasan ay mahalagang bahagi ng kurso."}];
const audioUrl = index => new URL(`./audio/${String(data[index].n).padStart(3,"0")}.mp3`, document.baseURI).href;
